import { AfterViewInit, Component, ElementRef, ViewChild, signal } from '@angular/core';

import { SCHEMA } from '../gerado/schema.gerado';
import { textoDoDiagrama } from './diagrama';

const ZOOM_MINIMO = 0.2;
const ZOOM_MAXIMO = 3;

/** Aba Dados: diagrama de entidades e relacionamentos inferido das telas. Somente leitura. */
@Component({
  selector: 'proto-dados',
  standalone: true,
  templateUrl: './dados.component.html',
  styleUrl: './dados.component.css',
})
export class DadosComponent implements AfterViewInit {
  protected readonly schema = SCHEMA;
  protected readonly confirmados = SCHEMA.relacionamentos.filter((r) => r.confianca === 'alta').length;
  protected readonly carregando = signal(SCHEMA.entidades.length > 0);
  protected readonly erro = signal<string | null>(null);
  protected readonly avisosAbertos = signal(false);

  @ViewChild('janela') private readonly janela?: ElementRef<HTMLElement>;
  @ViewChild('desenho') private readonly desenho?: ElementRef<HTMLElement>;

  protected readonly zoom = signal(1);
  protected readonly deslocamento = signal({ x: 0, y: 0 });
  private arrasto: { x: number; y: number; inicio: { x: number; y: number } } | null = null;

  async ngAfterViewInit(): Promise<void> {
    if (!this.schema.entidades.length) {
      return;
    }
    try {
      // Carregado sob demanda: o Mermaid só entra no bundle desta aba.
      const { default: mermaid } = await import('mermaid');
      mermaid.initialize({ startOnLoad: false, theme: 'neutral', securityLevel: 'strict', er: { useMaxWidth: false } });
      const { svg } = await mermaid.render(`proto-diagrama-${Date.now()}`, textoDoDiagrama(this.schema));
      this.desenho!.nativeElement.innerHTML = svg;
      this.carregando.set(false);
      requestAnimationFrame(() => this.ajustar());
    } catch (erro) {
      this.carregando.set(false);
      this.erro.set(erro instanceof Error ? erro.message : String(erro));
    }
  }

  protected aproximar(fator: number): void {
    const janela = this.janela?.nativeElement.getBoundingClientRect();
    if (janela) {
      this.zoomEm(fator, janela.width / 2, janela.height / 2);
    }
  }

  /** Enquadra o diagrama inteiro na janela. */
  protected ajustar(): void {
    const svg = this.desenho?.nativeElement.querySelector('svg');
    const janela = this.janela?.nativeElement;
    if (!svg || !janela) {
      return;
    }
    const largura = svg.viewBox.baseVal?.width || svg.getBoundingClientRect().width / this.zoom();
    const altura = svg.viewBox.baseVal?.height || svg.getBoundingClientRect().height / this.zoom();
    svg.setAttribute('width', String(largura));
    svg.setAttribute('height', String(altura));
    // Margem embaixo maior: a legenda fica fixa no canto inferior.
    const margem = 32;
    const espacoDaLegenda = 64;
    const alturaUtil = janela.clientHeight - margem * 2 - espacoDaLegenda;
    const escala = limitar(Math.min((janela.clientWidth - margem * 2) / largura, alturaUtil / altura));
    this.zoom.set(escala);
    this.deslocamento.set({
      x: (janela.clientWidth - largura * escala) / 2,
      y: margem + (alturaUtil - altura * escala) / 2,
    });
  }

  protected rolar(evento: WheelEvent): void {
    evento.preventDefault();
    const janela = this.janela!.nativeElement.getBoundingClientRect();
    this.zoomEm(evento.deltaY < 0 ? 1.1 : 1 / 1.1, evento.clientX - janela.left, evento.clientY - janela.top);
  }

  protected comecarArrasto(evento: PointerEvent): void {
    if (evento.button !== 0) {
      return;
    }
    (evento.currentTarget as HTMLElement).setPointerCapture(evento.pointerId);
    this.arrasto = { x: evento.clientX, y: evento.clientY, inicio: this.deslocamento() };
  }

  protected arrastar(evento: PointerEvent): void {
    if (this.arrasto) {
      const { x, y, inicio } = this.arrasto;
      this.deslocamento.set({ x: inicio.x + evento.clientX - x, y: inicio.y + evento.clientY - y });
    }
  }

  protected terminarArrasto(): void {
    this.arrasto = null;
  }

  /** Zoom mantendo parado o ponto (x, y) da janela. */
  private zoomEm(fator: number, x: number, y: number): void {
    const atual = this.zoom();
    const novo = limitar(atual * fator);
    const { x: dx, y: dy } = this.deslocamento();
    this.deslocamento.set({ x: x - ((x - dx) * novo) / atual, y: y - ((y - dy) * novo) / atual });
    this.zoom.set(novo);
  }
}

function limitar(zoom: number): number {
  return Math.min(ZOOM_MAXIMO, Math.max(ZOOM_MINIMO, zoom));
}

// Monta o texto do diagrama `erDiagram` do Mermaid a partir do schema gerado.
// Sintaxe conferida contra o Mermaid 12.3: apelido `id["nome"]`, comentário entre aspas, `..` tracejado.
import type { Atributo, Relacionamento, SchemaGerado } from '../modelo/tipos';

const PONTAS: Record<Relacionamento['cardinalidade'], [string, string]> = {
  '1:1': ['||', '||'],
  '1:N': ['||', 'o{'],
  'N:1': ['}o', '||'],
  'N:N': ['}o', 'o{'],
};

const ROTULOS: Record<Relacionamento['regra'], (campo: string) => string> = {
  aninhado: (campo) => `aninhado · ${campo}`,
  listaAninhada: (campo) => `lista aninhada · ${campo}`,
  referencia: (campo) => `campo ${campo}`,
  listaDeReferencias: (campo) => `campo ${campo}`,
  agrupamento: (campo) => `agrupado em ${campo}`,
};

/** Nome que o Mermaid aceita como identificador; o nome real vai no apelido. */
function identificador(nome: string): string {
  return nome.replace(/[^A-Za-z0-9_]/g, '_');
}

function semAspas(texto: string): string {
  return texto.replace(/"/g, "'").replace(/[\r\n]+/g, ' ');
}

function linhaDoAtributo(atributo: Atributo): string {
  const tipo = (atributo.tipos.length ? atributo.tipos.join('_ou_') : 'desconhecido') + (atributo.lista ? '[]' : '');
  const comentario = [atributo.opcional ? 'opcional' : null, atributo.exemplo !== null ? `ex.: ${atributo.exemplo}` : null]
    .filter(Boolean)
    .join(' · ');
  return [
    '    ' + tipo,
    identificador(atributo.nome),
    atributo.marca ?? '',
    comentario ? `"${semAspas(comentario)}"` : '',
  ]
    .filter(Boolean)
    .join(' ');
}

export function textoDoDiagrama(schema: SchemaGerado): string {
  const linhas = ['erDiagram'];
  for (const entidade of schema.entidades) {
    const id = identificador(entidade.nome);
    const cabecalho = id === entidade.nome ? id : `${id}["${semAspas(entidade.nome)}"]`;
    linhas.push(`  ${cabecalho} {`, ...entidade.atributos.map(linhaDoAtributo), '  }');
  }
  for (const relacionamento of schema.relacionamentos) {
    const [esquerda, direita] = PONTAS[relacionamento.cardinalidade];
    // Linha contínua: confirmada pelos dados; tracejada: provável.
    const traco = relacionamento.confianca === 'alta' ? '--' : '..';
    const rotulo = semAspas(ROTULOS[relacionamento.regra](relacionamento.campo));
    linhas.push(
      `  ${identificador(relacionamento.de)} ${esquerda}${traco}${direita} ${identificador(relacionamento.para)} : "${rotulo}"`,
    );
  }
  return linhas.join('\n');
}

// Copia a planilha de tags de `planilha.origem` para `planilha.arquivo` (prototipador.config.json).
// Rode a partir da raiz do projeto:  tsx src/app/prototipador/gerador/atualizar-planilha.ts
//
// Roda antes de cada `npm start` e `npm run build`. Nunca interrompe: sem origem configurada,
// origem inexistente ou cópia já atualizada, só imprime uma linha e termina com sucesso.
import { copyFileSync, existsSync, mkdirSync, statSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

import { lerConfiguracao } from './configuracao';

const raiz = process.cwd();

try {
  const { planilha } = lerConfiguracao(raiz);
  const destino = resolve(raiz, planilha.arquivo);

  if (!planilha.origem) {
    console.log('[proto] planilha: sem "planilha.origem" no prototipador.config.json; nada a copiar.');
  } else if (!existsSync(planilha.origem)) {
    console.log(`[proto] planilha: "${planilha.origem}" não encontrada nesta máquina; mantida a cópia do projeto.`);
  } else if (existsSync(destino) && statSync(destino).mtimeMs >= statSync(planilha.origem).mtimeMs) {
    console.log('[proto] planilha: cópia do projeto já está atualizada.');
  } else {
    mkdirSync(dirname(destino), { recursive: true });
    copyFileSync(planilha.origem, destino);
    console.log(`[proto] planilha: copiada de "${planilha.origem}".`);
  }
} catch (erro) {
  console.log(`[proto] planilha: não foi possível atualizar (${(erro as Error).message}).`);
}

import { existsSync, readFileSync } from 'node:fs';
import { basename, dirname, join, relative, resolve } from 'node:path';
import {
  CallExpression,
  ClassDeclaration,
  CompilerOptions,
  Decorator,
  Expression,
  Node,
  ObjectLiteralExpression,
  SourceFile,
  Type,
} from 'ts-morph';

import type { ComponenteRegistrado, InputRegistrado, OutputRegistrado } from '../../modelo/tipos';
import type { Configuracao } from '../configuracao';
import { NAO_LITERAL, textoFixo, valorLiteral } from '../literais';
import { Telas, abrirTelas, posix } from '../projeto';
import { CasadorDeSeletores } from './template';
import { converterTipo } from './tipos-de-campo';

/** Registro de um componente como o gerador o lê; `carregar` e `ajuste` viram código na escrita. */
export interface ComponenteLido extends Omit<ComponenteRegistrado, 'carregar' | 'ajuste'> {
  /** Caminho do `.proto.ts`, relativo à raiz, ou null se não houver. */
  arquivoAjuste: string | null;
}

/** Template de um componente, para quem mais lê os templates (ex.: as tags de tradução). */
export interface TemplateDoComponente {
  id: string;
  texto: string;
  /** Caminho absoluto do .html, ou do .ts quando o template é em linha. */
  arquivo: string;
  /** Linha do arquivo (base 0) onde o template começa: 0 no .html; a linha da crase no template em linha. */
  linhaInicial: number;
}

export interface LeituraDeComponentes {
  componentes: ComponenteLido[];
  templates: TemplateDoComponente[];
  /** Arquivos que não puderam ser lidos e outros problemas fora de um componente. */
  avisos: string[];
}


interface Metadados {
  seletor: string | null;
  standalone: boolean;
  template: { texto: string; arquivo: string; linhaInicial: number } | null;
}

/** Lê os componentes das telas. Recebe as telas já abertas, ou abre (para uso isolado, como nos testes). */
export function lerComponentes(
  raiz: string,
  config: Configuracao,
  opcoesDoCompilador: CompilerOptions = {},
  telas: Telas = abrirTelas(raiz, config, opcoesDoCompilador),
): LeituraDeComponentes {
  const avisos: string[] = [...telas.avisos];
  const pastaTelas = resolve(raiz, config.pastaTelas);

  // 1ª passada: encontrar os componentes e seus metadados.
  const encontrados: { classe: ClassDeclaration; metadados: Metadados; avisos: string[] }[] = [];
  for (const arquivo of telas.arquivos) {
    for (const classe of arquivo.getClasses()) {
      const decorador = classe.getDecorator('Component');
      if (decorador) {
        const avisosDoComponente: string[] = [];
        encontrados.push({ classe, metadados: lerMetadados(decorador, arquivo, avisosDoComponente), avisos: avisosDoComponente });
      }
    }
  }

  const idDe = (e: (typeof encontrados)[number]) => e.metadados.seletor ?? e.classe.getName() ?? '(sem nome)';
  const casador = new CasadorDeSeletores(encontrados.map((e) => ({ id: idDe(e), seletor: e.metadados.seletor })));
  for (const { id, erro } of casador.invalidos) {
    avisos.push(`Seletor inválido em "${id}": ${erro}`);
  }

  // 2ª passada: inputs, outputs e filhos.
  const componentes = encontrados.map(({ classe, metadados, avisos: avisosDoComponente }): ComponenteLido => {
    const arquivo = classe.getSourceFile().getFilePath();
    const nomeDaClasse = classe.getName() ?? '(sem nome)';
    if (!classe.isExported()) {
      avisosDoComponente.push(`A classe ${nomeDaClasse} não é exportada; a área de teste não consegue carregá-la.`);
    }

    let filhos: string[] = [];
    if (metadados.template) {
      try {
        const lido = casador.lerTemplate(metadados.template.texto, metadados.template.arquivo);
        filhos = lido.filhos;
        avisosDoComponente.push(...lido.erros.map((erro) => `Erro no template: ${erro}`));
      } catch (erro) {
        avisosDoComponente.push(`Não foi possível ler o template: ${(erro as Error).message}`);
      }
    }

    const { inputs, outputs } = lerEntradasESaidas(classe, avisosDoComponente);
    const nomeBase = basename(arquivo).replace(/(\.component)?\.ts$/, '');
    const pastaDoArquivo = dirname(arquivo);
    const ajuste = join(pastaDoArquivo, `${nomeBase}.proto.ts`);
    // Na convenção do Angular cada componente tem pasta própria (cartao/cartao.component.ts);
    // nesse caso o grupo é a pasta de cima, para não virar um grupo por componente.
    const pastaDoGrupo = basename(pastaDoArquivo) === nomeBase ? dirname(pastaDoArquivo) : pastaDoArquivo;
    const pasta = posix(relative(pastaTelas, pastaDoGrupo));

    return {
      id: metadados.seletor ?? nomeDaClasse,
      seletor: metadados.seletor,
      classe: nomeDaClasse,
      arquivo: posix(relative(raiz, arquivo)),
      pasta: pasta || '.',
      standalone: metadados.standalone,
      inputs,
      outputs,
      filhos,
      arquivoAjuste: existsSync(ajuste) ? posix(relative(raiz, ajuste)) : null,
      avisos: avisosDoComponente,
    };
  });

  const vistos = new Map<string, string>();
  for (const componente of componentes) {
    const anterior = vistos.get(componente.id);
    if (anterior) {
      avisos.push(`Dois componentes com o id "${componente.id}": ${anterior} e ${componente.arquivo}.`);
    }
    vistos.set(componente.id, componente.arquivo);
  }

  componentes.sort((a, b) => comparar(a.id, b.id) || comparar(a.arquivo, b.arquivo));
  const templates = encontrados
    .filter((e) => e.metadados.template)
    .map((e) => ({ id: idDe(e), ...e.metadados.template! }));
  return { componentes, templates, avisos };
}

// ---------- Metadados do @Component ----------

function lerMetadados(decorador: Decorator, arquivo: SourceFile, avisos: string[]): Metadados {
  const metadados: Metadados = { seletor: null, standalone: false, template: null };
  const argumento = decorador.getArguments()[0];
  if (!Node.isObjectLiteralExpression(argumento)) {
    avisos.push('O metadado do @Component não é um objeto literal; seletor e template não foram lidos.');
    return metadados;
  }

  const seletor = valorDaPropriedade(argumento, 'selector');
  if (seletor) {
    const texto = textoFixo(seletor);
    if (texto === undefined) {
      avisos.push('O seletor não é um texto fixo e não foi lido.');
    } else {
      metadados.seletor = texto.trim() || null;
    }
  }

  // No Angular 17, um componente sem `standalone` não é standalone.
  metadados.standalone = valorDaPropriedade(argumento, 'standalone')?.getKindName() === 'TrueKeyword';

  const template = valorDaPropriedade(argumento, 'template');
  const templateUrl = valorDaPropriedade(argumento, 'templateUrl');
  if (template) {
    const texto = textoFixo(template);
    if (texto === undefined) {
      avisos.push('O template em linha não é um texto fixo e não foi lido; os filhos não foram detectados.');
    } else {
      metadados.template = { texto, arquivo: arquivo.getFilePath(), linhaInicial: template.getStartLineNumber() - 1 };
    }
  } else if (templateUrl) {
    const url = textoFixo(templateUrl);
    const caminho = url === undefined ? undefined : resolve(dirname(arquivo.getFilePath()), url);
    if (caminho && existsSync(caminho)) {
      metadados.template = { texto: readFileSync(caminho, 'utf8'), arquivo: caminho, linhaInicial: 0 };
    } else {
      avisos.push(`O templateUrl "${url ?? templateUrl.getText()}" não foi encontrado; os filhos não foram detectados.`);
    }
  }

  if (valorDaPropriedade(argumento, 'inputs')) {
    avisos.push('Inputs declarados em "inputs: [...]" no metadado não são lidos.');
  }
  if (valorDaPropriedade(argumento, 'hostDirectives')) {
    avisos.push('Inputs vindos de "hostDirectives" não são lidos.');
  }
  return metadados;
}

// ---------- Inputs e outputs ----------

function lerEntradasESaidas(
  classe: ClassDeclaration,
  avisos: string[],
): { inputs: InputRegistrado[]; outputs: OutputRegistrado[] } {
  // Da classe base mais distante até a própria classe; quem vem depois sobrescreve.
  const cadeia: ClassDeclaration[] = [];
  for (let atual: ClassDeclaration | undefined = classe; atual; atual = atual.getBaseClass()) {
    if (atual.getSourceFile().isDeclarationFile()) {
      break;
    }
    cadeia.unshift(atual);
  }

  const inputs = new Map<string, InputRegistrado>();
  const outputs = new Map<string, OutputRegistrado>();

  for (const atual of cadeia) {
    for (const membro of atual.getMembers()) {
      if (Node.isPropertyDeclaration(membro)) {
        const propriedade = membro.getName();
        const decoradorDeInput = membro.getDecorator('Input');
        const decoradorDeOutput = membro.getDecorator('Output');
        const inicial = membro.getInitializer();

        if (decoradorDeInput) {
          const { alias, obrigatorio } = lerDecoradorDeInput(decoradorDeInput);
          const padrao = inicial ? valorLiteral(inicial) : NAO_LITERAL;
          inputs.set(propriedade, montarInput({
            nome: alias ?? propriedade,
            propriedade,
            tipo: membro.getType(),
            local: membro,
            opcional: !obrigatorio || membro.hasQuestionToken(),
            padrao,
            avisos,
          }));
        } else if (decoradorDeOutput) {
          const alias = decoradorDeOutput.getArguments()[0];
          outputs.set(propriedade, { nome: (alias && textoFixo(alias)) ?? propriedade, propriedade });
        } else if (inicial && Node.isCallExpression(inicial)) {
          lerFuncaoDeSinal(inicial, propriedade, membro.getType(), membro, inputs, outputs, avisos);
        }
      } else if (Node.isSetAccessorDeclaration(membro) || Node.isGetAccessorDeclaration(membro)) {
        const decorador = membro.getDecorator('Input');
        if (!decorador) {
          continue;
        }
        const propriedade = membro.getName();
        const { alias, obrigatorio } = lerDecoradorDeInput(decorador);
        const tipo = Node.isSetAccessorDeclaration(membro)
          ? membro.getParameters()[0]?.getType()
          : membro.getReturnType();
        if (!tipo) {
          avisos.push(`O setter do input "${propriedade}" não tem parâmetro.`);
          continue;
        }
        inputs.set(propriedade, montarInput({
          nome: alias ?? propriedade,
          propriedade,
          tipo,
          local: membro,
          opcional: !obrigatorio,
          padrao: NAO_LITERAL,
          avisos,
        }));
      }
    }
  }
  return { inputs: [...inputs.values()], outputs: [...outputs.values()] };
}

/** `input()`, `input.required()`, `model()`, `model.required()` e `output()`. */
function lerFuncaoDeSinal(
  chamada: CallExpression,
  propriedade: string,
  tipoDaPropriedade: Type,
  local: Node,
  inputs: Map<string, InputRegistrado>,
  outputs: Map<string, OutputRegistrado>,
  avisos: string[],
): void {
  const funcao = chamada.getExpression().getText().replace(/\s/g, '');
  const argumentos = chamada.getArguments();
  const obrigatorio = funcao.endsWith('.required');
  const base = funcao.replace(/\.required$/, '');

  if (base === 'output') {
    outputs.set(propriedade, { nome: aliasDasOpcoes(argumentos[0]) ?? propriedade, propriedade });
    return;
  }
  if (base !== 'input' && base !== 'model') {
    return;
  }

  // `required` recebe as opções no 1º argumento; os outros recebem o valor inicial e depois as opções.
  const opcoes = obrigatorio ? argumentos[0] : argumentos[1];
  const nome = aliasDasOpcoes(opcoes) ?? propriedade;
  // InputSignal<T> e ModelSignal<T>: o tipo do valor é o primeiro argumento de tipo.
  const tipo = tipoDaPropriedade.getTypeArguments()[0] ?? tipoDaPropriedade.getAliasTypeArguments()[0];
  if (!tipo) {
    avisos.push(`Não foi possível ler o tipo do input "${nome}".`);
    return;
  }
  inputs.set(propriedade, montarInput({
    nome,
    propriedade,
    tipo,
    local,
    opcional: !obrigatorio,
    padrao: !obrigatorio && argumentos[0] ? valorLiteral(argumentos[0]) : NAO_LITERAL,
    avisos,
  }));
  if (base === 'model') {
    outputs.set(`${propriedade}Change`, { nome: `${nome}Change`, propriedade });
  }
}

function montarInput(dados: {
  nome: string;
  propriedade: string;
  tipo: Type;
  local: Node;
  opcional: boolean;
  padrao: unknown;
  avisos: string[];
}): InputRegistrado {
  const convertido = converterTipo(dados.tipo, dados.local, dados.nome, dados.avisos);
  const input: InputRegistrado = {
    nome: dados.nome,
    propriedade: dados.propriedade,
    tipo: convertido.tipo,
    opcional: dados.opcional || convertido.opcional,
    aceitaNulo: convertido.aceitaNulo,
  };
  if (dados.padrao !== NAO_LITERAL) {
    input.padrao = dados.padrao;
  }
  return input;
}

function lerDecoradorDeInput(decorador: Decorator): { alias: string | null; obrigatorio: boolean } {
  const argumento = decorador.getArguments()[0];
  if (!argumento) {
    return { alias: null, obrigatorio: false };
  }
  if (Node.isObjectLiteralExpression(argumento)) {
    return {
      alias: aliasDasOpcoes(argumento),
      obrigatorio: valorDaPropriedade(argumento, 'required')?.getKindName() === 'TrueKeyword',
    };
  }
  return { alias: textoFixo(argumento) ?? null, obrigatorio: false };
}

// ---------- Utilitários ----------

function aliasDasOpcoes(opcoes: Node | undefined): string | null {
  if (!opcoes || !Node.isObjectLiteralExpression(opcoes)) {
    return null;
  }
  const alias = valorDaPropriedade(opcoes, 'alias');
  return (alias && textoFixo(alias)) ?? null;
}

function valorDaPropriedade(objeto: ObjectLiteralExpression, nome: string): Expression | undefined {
  const propriedade = objeto.getProperty(nome);
  return propriedade && Node.isPropertyAssignment(propriedade) ? propriedade.getInitializer() : undefined;
}

function comparar(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

// Único módulo do gerador que usa o analisador de templates do @angular/compiler.
// A API muda entre versões do Angular; conferida contra a 17.3.
import {
  AST,
  ASTWithSource,
  BindingPipe,
  Conditional,
  CssSelector,
  LiteralPrimitive,
  RecursiveAstVisitor,
  SelectorMatcher,
  TmplAstBoundText,
  TmplAstDeferredBlock,
  TmplAstElement,
  TmplAstForLoopBlock,
  TmplAstIfBlock,
  TmplAstRecursiveVisitor,
  TmplAstSwitchBlock,
  TmplAstTemplate,
  TmplAstText,
  parseTemplate,
  tmplAstVisitAll,
} from '@angular/compiler';
import type { TmplAstBoundAttribute, TmplAstBoundEvent, TmplAstNode, TmplAstTextAttribute } from '@angular/compiler';

/** Tipo de ligação "propriedade" em TmplAstBoundAttribute (os outros são attr., class., style. e animação). */
const LIGACAO_DE_PROPRIEDADE = 0;

export interface ResultadoDoTemplate {
  /** Ids dos componentes cujo seletor casa com algum elemento do template. */
  filhos: string[];
  erros: string[];
}

/** Casa elementos do template com seletores de componentes, como o Angular faz. */
export class CasadorDeSeletores {
  private readonly casador = new SelectorMatcher<string>();
  readonly invalidos: { id: string; erro: string }[] = [];

  constructor(componentes: { id: string; seletor: string | null }[]) {
    for (const { id, seletor } of componentes) {
      if (!seletor) {
        continue;
      }
      try {
        this.casador.addSelectables(CssSelector.parse(seletor), id);
      } catch (erro) {
        this.invalidos.push({ id, erro: (erro as Error).message });
      }
    }
  }

  lerTemplate(template: string, arquivo: string): ResultadoDoTemplate {
    const analisado = parseTemplate(template, arquivo, { preserveWhitespaces: false });
    const filhos = new Set<string>();
    const casador = this.casador;

    const casar = (
      nome: string,
      atributos: TmplAstTextAttribute[],
      entradas: TmplAstBoundAttribute[],
      saidas: TmplAstBoundEvent[],
    ): void => {
      const seletor = new CssSelector();
      seletor.setElement(nome);
      for (const atributo of atributos) {
        seletor.addAttribute(atributo.name, atributo.value);
        if (atributo.name.toLowerCase() === 'class') {
          atributo.value.split(/\s+/).filter(Boolean).forEach((classe) => seletor.addClassName(classe));
        }
      }
      for (const entrada of entradas) {
        if (entrada.type === LIGACAO_DE_PROPRIEDADE) {
          seletor.addAttribute(entrada.name, '');
        }
      }
      for (const saida of saidas) {
        seletor.addAttribute(saida.name, '');
      }
      casador.match(seletor, (_, id) => filhos.add(id));
    };

    class Visitante extends TmplAstRecursiveVisitor {
      override visitElement(elemento: TmplAstElement): void {
        casar(elemento.name, elemento.attributes, elemento.inputs, elemento.outputs);
        super.visitElement(elemento);
      }

      override visitTemplate(template: TmplAstTemplate): void {
        // Diretivas estruturais (`*x`) ficam em templateAttrs do <ng-template> sintético.
        const atributos = [...template.attributes, ...template.templateAttrs].filter(
          (a): a is TmplAstTextAttribute => !('type' in a),
        );
        const entradas = [...template.inputs, ...template.templateAttrs].filter(
          (a): a is TmplAstBoundAttribute => 'type' in a,
        );
        casar('ng-template', atributos, entradas, template.outputs);
        super.visitTemplate(template);
      }
    }

    tmplAstVisitAll(new Visitante(), analisado.nodes as TmplAstNode[]);
    return {
      filhos: [...filhos].sort(),
      erros: (analisado.errors ?? []).map((erro) => erro.toString()),
    };
  }
}

// ---------- Tags de tradução no template ----------

/** Um uso do pipe (ou da diretiva) de tradução no template. */
export interface UsoNoTemplate {
  /** null quando a chave não é um texto fixo (chave dinâmica). */
  chave: string | null;
  /** Expressão da chave como está no código. */
  expressao: string;
  papel: string;
  condicao: string | null;
  /** Linha no template, base 0. */
  linha: number;
}

/** Tipo de ligação `attr.x` em TmplAstBoundAttribute. */
const LIGACAO_DE_ATRIBUTO = 1;

/**
 * Encontra as tags de tradução: `'chave' | pipe`, `<el pipe>chave</el>` e `[pipe]="'chave'"`.
 * Uma chave escolhida por ternário entre textos fixos conta como as duas chaves fixas.
 */
export function lerTagsDoTemplate(template: string, arquivo: string, pipe: string): UsoNoTemplate[] {
  const analisado = parseTemplate(template, arquivo, { preserveWhitespaces: false });
  const usos: UsoNoTemplate[] = [];
  const textoDe = (ast: AST): string =>
    ast instanceof ASTWithSource ? (ast.source ?? '') : template.slice(ast.sourceSpan.start, ast.sourceSpan.end);

  const chavesFixas = (ast: AST): string[] | null => {
    if (ast instanceof LiteralPrimitive && typeof ast.value === 'string') return [ast.value];
    if (ast instanceof Conditional) {
      const sim = chavesFixas(ast.trueExp);
      const nao = chavesFixas(ast.falseExp);
      return sim && nao ? [...sim, ...nao] : null;
    }
    return null;
  };

  const registrar = (chaveAst: AST, papel: string, condicao: string | null, linha: number) => {
    const chaves = chavesFixas(chaveAst);
    const expressao = textoDe(chaveAst);
    if (chaves) {
      chaves.forEach((chave) => usos.push({ chave, expressao, papel, condicao, linha }));
    } else {
      usos.push({ chave: null, expressao, papel, condicao, linha });
    }
  };

  /** Todos os usos do pipe dentro de uma expressão (inclusive aninhados). */
  const registrarPipes = (valor: AST, papel: string, condicao: string | null, linha: number) => {
    const pipes: BindingPipe[] = [];
    class Coletor extends RecursiveAstVisitor {
      override visitPipe(ast: BindingPipe, contexto: unknown): unknown {
        if (ast.name === pipe) pipes.push(ast);
        return super.visitPipe(ast, contexto);
      }
    }
    (valor instanceof ASTWithSource ? valor.ast : valor).visit(new Coletor());
    pipes.forEach((p) => registrar(p.exp, papel, condicao, linha));
  };

  const andar = (nos: TmplAstNode[], elemento: string | null, condicao: string | null): void => {
    for (const no of nos) {
      if (no instanceof TmplAstElement) {
        const linha = no.sourceSpan.start.line;
        // Diretiva com a chave no conteúdo: <el translate>chave</el>
        if (no.attributes.some((a) => a.name === pipe)) {
          const chave = no.children.filter((f): f is TmplAstText => f instanceof TmplAstText).map((f) => f.value).join('').trim();
          if (chave) usos.push({ chave, expressao: chave, papel: papelDoTexto(no.name), condicao, linha });
        }
        for (const entrada of no.inputs) {
          if (entrada.name === pipe) {
            // Diretiva com a chave vinculada: [translate]="'chave'"
            const valor = entrada.value instanceof ASTWithSource ? entrada.value.ast : entrada.value;
            registrar(valor, papelDoTexto(no.name), condicao, entrada.sourceSpan.start.line);
          } else {
            registrarPipes(entrada.value, papelDaPropriedade(entrada, no.name), condicao, entrada.sourceSpan.start.line);
          }
        }
        andar(no.children, no.name, condicao);
      } else if (no instanceof TmplAstTemplate) {
        // Diretiva estrutural: *ngIf
        const ngIf = no.templateAttrs.find((a) => a.name === 'ngIf' && 'value' in a && a.value instanceof ASTWithSource);
        const novaCondicao = ngIf ? `aparece quando: \`${textoDe((ngIf as TmplAstBoundAttribute).value)}\`` : condicao;
        for (const entrada of no.inputs) {
          registrarPipes(entrada.value, papelDaPropriedade(entrada, no.tagName ?? 'ng-template'), novaCondicao, entrada.sourceSpan.start.line);
        }
        andar(no.children, elemento, novaCondicao);
      } else if (no instanceof TmplAstBoundText) {
        registrarPipes(no.value, papelDoTexto(elemento), condicao, no.sourceSpan.start.line);
      } else if (no instanceof TmplAstIfBlock) {
        no.branches.forEach((ramo, i) => {
          const anterior = no.branches[i - 1]?.expression;
          const cond = ramo.expression
            ? `aparece quando: \`${textoDe(ramo.expression)}\``
            : `senão de: \`${anterior ? textoDe(anterior) : '?'}\``;
          andar(ramo.children, elemento, cond);
        });
      } else if (no instanceof TmplAstForLoopBlock) {
        andar(no.children, elemento, condicao);
        if (no.empty) andar(no.empty.children, elemento, `lista vazia de: \`${textoDe(no.expression)}\``);
      } else if (no instanceof TmplAstSwitchBlock) {
        const sobre = textoDe(no.expression);
        for (const caso of no.cases) {
          const cond = caso.expression
            ? `aparece quando: \`${sobre} === ${textoDe(caso.expression)}\``
            : `senão de: \`${sobre}\` (nenhum caso)`;
          andar(caso.children, elemento, cond);
        }
      } else if (no instanceof TmplAstDeferredBlock) {
        andar(no.children, elemento, condicao);
        for (const parte of [no.placeholder, no.loading, no.error]) {
          if (parte) andar(parte.children, elemento, condicao);
        }
      } else if ('children' in no && Array.isArray((no as { children: unknown }).children)) {
        andar((no as unknown as { children: TmplAstNode[] }).children, elemento, condicao);
      }
    }
  };

  andar(analisado.nodes as TmplAstNode[], null, null);
  return usos;
}

const TITULOS = new Set(['h1', 'h2', 'h3', 'h4', 'h5', 'h6']);

function papelDoTexto(elemento: string | null): string {
  if (!elemento) return 'texto';
  if (elemento === 'button') return 'rótulo do botão';
  if (elemento === 'label') return 'rótulo de campo';
  if (TITULOS.has(elemento)) return 'título';
  if (elemento === 'th') return 'cabeçalho de coluna';
  if (elemento === 'a') return 'link';
  return `texto em ${elemento}`;
}

function papelDaPropriedade(entrada: TmplAstBoundAttribute, elemento: string): string {
  const nome = entrada.name;
  if (nome === 'label' && (elemento === 'p-button' || elemento === 'button')) return 'rótulo do botão';
  if (nome === 'placeholder') return 'placeholder do campo';
  if (nome === 'pTooltip' || nome === 'title') return 'tooltip';
  if (nome === 'header') return elemento === 'th' || elemento === 'p-column' ? 'cabeçalho de coluna' : `título de ${elemento}`;
  if (nome === 'aria-label' || nome === 'ariaLabel' || (entrada.type === LIGACAO_DE_ATRIBUTO && nome === 'aria-label')) return 'rótulo acessível';
  return `propriedade ${nome} de ${elemento}`;
}

import { Node, Type, TypeFormatFlags, ts } from 'ts-morph';

import type { Campo, TipoCampo } from '../../modelo/tipos';

/** Objetos aninhados além deste nível viram `naoEditavel`. */
const PROFUNDIDADE_MAXIMA = 5;

/** Tipos que nunca são dado editável, com o motivo mostrado no aviso. */
const MOTIVOS_POR_NOME: Record<string, string> = {
  TemplateRef: 'TemplateRef',
  Observable: 'Observable',
  Subject: 'Observable',
  BehaviorSubject: 'Observable',
  ReplaySubject: 'Observable',
  EventEmitter: 'Observable',
  Promise: 'Promise',
  ElementRef: 'referência a elemento',
  Map: 'Map',
  Set: 'Set',
};

export interface CampoConvertido {
  tipo: TipoCampo;
  opcional: boolean;
  aceitaNulo: boolean;
}

interface Contexto {
  /** Nó de referência para escrever tipos e resolver propriedades. */
  local: Node;
  /** Caminho do campo, para os avisos (ex.: `branch.descricao`). */
  caminho: string;
  avisos: string[];
  /** Tipos objeto em aberto, do mais externo ao mais interno. */
  pilha: ts.Type[];
}

/** Converte o tipo TypeScript de um input no tipo de campo editável da área de teste. */
export function converterTipo(tipo: Type, local: Node, caminho: string, avisos: string[]): CampoConvertido {
  return converter(tipo, { local, caminho, avisos, pilha: [] });
}

function converter(tipo: Type, contexto: Contexto): CampoConvertido {
  let opcional = false;
  let aceitaNulo = false;
  const membros = (tipo.isUnion() ? tipo.getUnionTypes() : [tipo]).filter((membro) => {
    if (membro.isNull()) {
      aceitaNulo = true;
      return false;
    }
    if (membro.isUndefined()) {
      opcional = true;
      return false;
    }
    return true;
  });
  return { tipo: converterMembros(tipo, membros, contexto), opcional, aceitaNulo };
}

function converterMembros(original: Type, membros: Type[], contexto: Contexto): TipoCampo {
  if (membros.length === 0) {
    return naoEditavel(original, 'só aceita nulo ou indefinido', contexto);
  }
  if (membros.length > 1) {
    // `boolean` chega aqui como a união `true | false`.
    if (membros.every((membro) => membro.isBooleanLiteral())) {
      return { tipo: 'booleano' };
    }
    const valores = membros.map(valorLiteral);
    if (valores.every((valor): valor is string | number => valor !== undefined)) {
      return { tipo: 'opcoes', valores };
    }
    return naoEditavel(original, 'união de tipos diferentes', contexto);
  }
  return converterUnico(membros[0], contexto);
}

function converterUnico(tipo: Type, contexto: Contexto): TipoCampo {
  if (tipo.isAny()) {
    return naoEditavel(tipo, 'any', contexto);
  }
  if (tipo.isUnknown()) {
    return naoEditavel(tipo, 'unknown', contexto);
  }
  if (tipo.isTypeParameter()) {
    return naoEditavel(tipo, 'parâmetro genérico', contexto);
  }
  if (tipo.isString()) {
    return { tipo: 'texto' };
  }
  if (tipo.isNumber()) {
    return { tipo: 'numero' };
  }
  if (tipo.isBoolean() || tipo.isBooleanLiteral()) {
    return { tipo: 'booleano' };
  }
  const literal = valorLiteral(tipo);
  if (literal !== undefined) {
    return { tipo: 'opcoes', valores: [literal] };
  }

  // Apelidos como `Signal<T>` só têm nome no símbolo do apelido; os outros, no símbolo do tipo.
  const nomes = [tipo.getAliasSymbol()?.getName(), tipo.getSymbol()?.getName()].filter((n): n is string => !!n);
  if (nomes.includes('Date')) {
    return { tipo: 'data' };
  }
  const motivo = nomes.map((n) => MOTIVOS_POR_NOME[n]).find(Boolean);
  if (motivo) {
    return naoEditavel(tipo, motivo, contexto);
  }
  if (tipo.getCallSignatures().length > 0) {
    return naoEditavel(tipo, nomes.some((n) => /Signal/.test(n)) ? 'signal' : 'função', contexto);
  }
  if (tipo.isTuple()) {
    return naoEditavel(tipo, 'tupla', contexto);
  }
  if (tipo.isArray() || nomes.includes('ReadonlyArray')) {
    const item = tipo.isArray() ? tipo.getArrayElementTypeOrThrow() : tipo.getTypeArguments()[0];
    if (!item) {
      return naoEditavel(tipo, 'lista sem tipo de item', contexto);
    }
    // A nulidade do item não tem onde ser registrada em `lista`; vale só o tipo.
    return { tipo: 'lista', item: converter(item, { ...contexto, caminho: `${contexto.caminho}[]` }).tipo };
  }
  if (tipo.isObject() || tipo.isIntersection()) {
    return converterObjeto(tipo, contexto);
  }
  return naoEditavel(tipo, 'tipo não suportado', contexto);
}

function converterObjeto(tipo: Type, contexto: Contexto): TipoCampo {
  if (contexto.pilha.includes(tipo.compilerType)) {
    return naoEditavel(tipo, 'tipo que se refere a si mesmo', contexto);
  }
  if (contexto.pilha.length >= PROFUNDIDADE_MAXIMA) {
    return naoEditavel(tipo, `aninhamento além de ${PROFUNDIDADE_MAXIMA} níveis`, contexto);
  }
  const propriedades = tipo.getProperties();
  if (propriedades.length === 0 && (tipo.getStringIndexType() || tipo.getNumberIndexType())) {
    return naoEditavel(tipo, 'dicionário com chaves livres', contexto);
  }

  const temMetodos = propriedades.some((propriedade) =>
    propriedade
      .getDeclarations()
      .some((declaracao) => Node.isMethodDeclaration(declaracao) || Node.isMethodSignature(declaracao)),
  );
  if (temMetodos) {
    return naoEditavel(tipo, 'objeto com métodos', contexto);
  }

  const pilha = [...contexto.pilha, tipo.compilerType];
  const campos: Campo[] = propriedades.map((propriedade) => {
    const nome = propriedade.getName();
    const convertido = converter(propriedade.getTypeAtLocation(contexto.local), {
      ...contexto,
      caminho: `${contexto.caminho}.${nome}`,
      pilha,
    });
    return {
      nome,
      tipo: convertido.tipo,
      opcional: convertido.opcional || propriedade.hasFlags(ts.SymbolFlags.Optional),
      aceitaNulo: convertido.aceitaNulo,
    };
  });
  return { tipo: 'objeto', campos };
}

function valorLiteral(tipo: Type): string | number | undefined {
  if (tipo.isStringLiteral() || tipo.isNumberLiteral() || tipo.isEnumLiteral()) {
    const valor = tipo.getLiteralValue();
    return typeof valor === 'string' || typeof valor === 'number' ? valor : undefined;
  }
  return undefined;
}

function naoEditavel(tipo: Type, motivo: string, contexto: Contexto): TipoCampo {
  const textoDoTipo = tipo.getText(
    contexto.local,
    TypeFormatFlags.UseAliasDefinedOutsideCurrentScope | TypeFormatFlags.NoTruncation,
  );
  contexto.avisos.push(`Input "${contexto.caminho}" não é editável: ${motivo} (tipo ${textoDoTipo}).`);
  return { tipo: 'naoEditavel', textoDoTipo, motivo };
}

import { readFileSync } from 'node:fs';
import { join } from 'node:path';

/** Formato do `prototipador.config.json` (ver docs/prototipador/00-visao-geral.md). */
export interface Configuracao {
  pastaTelas: string;
  mocks: string;
  i18n: {
    pasta: string;
    idiomas: Record<string, string>;
  };
  traducao: { pipe: string; servico: string };
  /**
   * `arquivo`: o CSV que o gerador lê. `origem` (opcional): caminho absoluto da planilha exportada
   * na máquina de quem prototipa; `npm run proto:planilha` copia de `origem` para `arquivo`.
   */
  planilha: { arquivo: string; colunaChave: string; origem?: string };
}

export const ARQUIVO_CONFIGURACAO = 'prototipador.config.json';

export function lerConfiguracao(raiz: string): Configuracao {
  const caminho = join(raiz, ARQUIVO_CONFIGURACAO);
  let bruto: unknown;
  try {
    bruto = JSON.parse(readFileSync(caminho, 'utf8'));
  } catch (erro) {
    throw new Error(`Não foi possível ler ${ARQUIVO_CONFIGURACAO}: ${(erro as Error).message}`);
  }
  const config = bruto as Partial<Configuracao>;
  const faltando = (['pastaTelas', 'mocks', 'i18n', 'traducao', 'planilha'] as const).filter(
    (campo) => config[campo] === undefined,
  );
  if (faltando.length) {
    throw new Error(`${ARQUIVO_CONFIGURACAO} sem os campos: ${faltando.join(', ')}`);
  }
  return config as Configuracao;
}

import { basename, relative } from 'node:path';
import { Node, Type, ts } from 'ts-morph';

import type { Atributo, Entidade, Relacionamento, SchemaGerado, TipoObservado } from '../../modelo/tipos';
import type { Configuracao } from '../configuracao';
import { NAO_LITERAL, valorLiteral } from '../literais';
import { Telas, posix } from '../projeto';

/**
 * Infere o schema a partir das telas (ver docs/prototipador/03-dados.md, adaptado):
 * - entidades: os tipos que os serviços das telas devolvem e os tipos das constantes de dados;
 * - atributos e relacionamentos estruturais: a declaração desses tipos;
 * - registros, exemplos, opcionais e referências confirmadas: os valores fixos das constantes
 *   (lidos sem executar o código).
 */

type Registro = Record<string, unknown>;

interface EntidadeEmMontagem {
  nome: string;
  origens: { arquivo: string; exportacao: string }[];
  /** Tipo declarado; ausente quando a entidade vem de um mock sem anotação. */
  tipo: Type | null;
  local: Node | null;
  registros: Registro[];
}

interface Agrupamento {
  entidade: string;
  campo: string;
  chaves: string[];
}

const TAMANHO_DO_EXEMPLO = 40;
const SEMELHANCA_MINIMA = 0.8;

export function lerDados(raiz: string, config: Configuracao, telas: Telas): SchemaGerado {
  const avisos: string[] = [];
  const caminhosDasTelas = new Set(telas.arquivos.map((arquivo) => arquivo.getFilePath()));
  const entidades = new Map<string, EntidadeEmMontagem>();
  const agrupamentos: Agrupamento[] = [];
  const caminho = (no: Node) => posix(relative(raiz, no.getSourceFile().getFilePath()));
  const ehMock = criarTesteDeMock(config.mocks);

  const registrar = (nome: string, tipo: Type | null, local: Node | null, origem?: { arquivo: string; exportacao: string }) => {
    let entidade = entidades.get(nome);
    if (!entidade) {
      entidade = { nome, origens: [], tipo, local, registros: [] };
      entidades.set(nome, entidade);
    }
    if (!entidade.tipo && tipo) {
      entidade.tipo = tipo;
      entidade.local = local;
    }
    if (origem && !entidade.origens.some((o) => o.arquivo === origem.arquivo && o.exportacao === origem.exportacao)) {
      entidade.origens.push(origem);
    }
    return entidade;
  };

  /** O tipo é uma entidade quando é um objeto com nome, declarado nas telas (não é serviço nem componente). */
  const entidadeDoTipo = (tipo: Type): { nome: string; tipo: Type; declaracao: Node } | null => {
    const objeto = desembrulhar(tipo);
    if (!objeto.isObject() || objeto.isArray() || objeto.getCallSignatures().length > 0) {
      return null;
    }
    const simbolo = objeto.getAliasSymbol() ?? objeto.getSymbol();
    const declaracao = simbolo
      ?.getDeclarations()
      .find((d) => Node.isInterfaceDeclaration(d) || Node.isTypeAliasDeclaration(d) || Node.isClassDeclaration(d));
    if (!simbolo || !declaracao || !caminhosDasTelas.has(declaracao.getSourceFile().getFilePath())) {
      return null;
    }
    if (Node.isClassDeclaration(declaracao) && (declaracao.getDecorators().length > 0 || herdaDeErro(objeto))) {
      return null;
    }
    return { nome: simbolo.getName(), tipo: objeto, declaracao };
  };

  // 1. O que os serviços das telas devolvem.
  for (const arquivo of telas.arquivos) {
    for (const classe of arquivo.getClasses()) {
      if (!classe.getDecorator('Injectable')) {
        continue;
      }
      for (const metodo of classe.getMethods()) {
        if (metodo.hasModifier(ts.SyntaxKind.PrivateKeyword) || metodo.hasModifier(ts.SyntaxKind.ProtectedKeyword) || metodo.isStatic()) {
          continue;
        }
        const encontrada = entidadeDoTipo(metodo.getReturnType());
        if (encontrada) {
          registrar(encontrada.nome, encontrada.tipo, encontrada.declaracao, {
            arquivo: caminho(metodo),
            exportacao: `${classe.getName()}.${metodo.getName()}()`,
          });
        }
      }
    }
  }

  // 2. As constantes de dados: listas de objetos, objetos e listas agrupadas por chave.
  for (const arquivo of telas.arquivos) {
    for (const declaracao of arquivo.getVariableDeclarations()) {
      const inicial = declaracao.getInitializer();
      if (!inicial || !Node.isSourceFile(declaracao.getVariableStatement()?.getParent() ?? inicial)) {
        continue;
      }
      const nomeDaConstante = declaracao.getName();
      const origem = { arquivo: caminho(declaracao), exportacao: nomeDaConstante };
      const valor = valorLiteral(inicial);
      const tipoDeclarado = declaracao.getType();

      if (valor === NAO_LITERAL) {
        const encontrada = entidadeDoTipo(tipoDeclarado);
        if (encontrada) {
          avisos.push(`${origem.arquivo}: ${nomeDaConstante} não é feito só de valores fixos; os registros não foram lidos.`);
        }
        continue;
      }

      const lista = listaDeObjetos(valor);
      const grupos = !lista && objetoDeListas(valor);
      const objeto = !lista && !grupos && ehObjetoSimples(valor) ? [valor as Registro] : null;
      const registros = lista ?? (grupos ? Object.values(grupos).flat() : objeto);
      if (!registros?.length) {
        continue;
      }

      const tipoDoItem = grupos ? (tipoDeclarado.getStringIndexType() ?? tipoDeclarado.getProperties()[0]?.getTypeAtLocation(declaracao)) : tipoDeclarado;
      const encontrada = tipoDoItem ? entidadeDoTipo(tipoDoItem) : null;
      let nome = encontrada?.nome;
      // Sem tipo com nome, só os mocks viram entidade (pelo nome do export, como na especificação).
      if (!nome && ehMock(arquivo.getFilePath())) {
        nome = nomePeloExport(nomeDaConstante);
      }
      if (!nome) {
        continue;
      }
      const entidade = registrar(nome, encontrada?.tipo ?? null, encontrada?.declaracao ?? null, origem);
      entidade.registros.push(...registros);
      if (grupos) {
        agrupamentos.push({ entidade: nome, campo: nomeDaConstante, chaves: Object.keys(grupos) });
      }
    }
  }

  // O mesmo registro pode aparecer em várias constantes (ex.: um almoxarifado em várias filiais).
  for (const entidade of entidades.values()) {
    entidade.registros = semRepetidos(entidade.registros);
  }

  // 3. Atributos e relacionamentos estruturais. Objetos aninhados podem criar entidades novas.
  const prontas = new Map<string, Entidade>();
  const relacionamentos: Relacionamento[] = [];
  const pendentes = [...entidades.keys()];
  while (pendentes.length) {
    const nome = pendentes.shift()!;
    if (prontas.has(nome)) {
      continue;
    }
    const entidade = entidades.get(nome)!;
    const atributos: Atributo[] = [];
    const aninhar = (campo: string, alvo: EntidadeEmMontagem, lista: boolean) => {
      relacionamentos.push({
        de: nome,
        para: alvo.nome,
        cardinalidade: lista ? '1:N' : '1:1',
        regra: lista ? 'listaAninhada' : 'aninhado',
        campo,
        confianca: 'alta',
      });
      if (!prontas.has(alvo.nome)) {
        pendentes.push(alvo.nome);
      }
    };

    for (const campo of camposDe(entidade)) {
      const valores = entidade.registros.map((registro) => registro[campo.nome]);
      const objetosNosDados = valores.flatMap((v) => (Array.isArray(v) ? v : [v])).filter(ehObjetoSimples) as Registro[];

      if (campo.forma === 'objeto' || campo.forma === 'listaDeObjetos' || (!campo.tipo && objetosNosDados.length)) {
        const lista = campo.forma === 'listaDeObjetos' || valores.some(Array.isArray);
        const declarada = campo.tipo ? entidadeDoTipo(campo.tipo) : null;
        const alvo = declarada
          ? registrar(declarada.nome, declarada.tipo, declarada.declaracao)
          : entidadeParaObjetos(nome, campo.nome, objetosNosDados, campo.tipo, entidade.local, entidades, prontas);
        alvo.registros = semRepetidos([...alvo.registros, ...objetosNosDados]);
        aninhar(campo.nome, alvo, lista);
        continue;
      }
      if (campo.forma === 'ignorar') {
        continue;
      }

      // Os valores mandam (ex.: texto com datas ISO é data); sem valores, vale o tipo declarado.
      const observados = new Set(
        valores.flatMap((v) => (Array.isArray(v) ? v : [v])).map(tipoObservado).filter((t): t is TipoObservado => !!t),
      );
      const tipos = observados.size ? observados : new Set<TipoObservado>(campo.tiposDeclarados);
      const exemplo = valores.find((v) => v !== null && v !== undefined);
      atributos.push({
        nome: campo.nome,
        tipos: [...tipos],
        ...(campo.forma === 'listaSimples' || valores.some(Array.isArray) ? { lista: true } : {}),
        opcional: campo.opcional || valores.some((v) => v === null || v === undefined),
        exemplo: exemplo === undefined ? null : resumirExemplo(exemplo),
        marca: null,
      });
    }

    prontas.set(nome, {
      nome,
      origens: [...entidade.origens].sort((a, b) => (a.arquivo + a.exportacao < b.arquivo + b.exportacao ? -1 : 1)),
      registros: entidade.registros.length,
      atributos,
    });
  }

  // 4. Chave primária: `id`; sem `id`, `codigo`/`code` quando os dados mostram valores únicos.
  const chaves = new Map<string, { atributo: string; valores: Set<unknown> }>();
  for (const entidade of prontas.values()) {
    const registros = entidades.get(entidade.nome)!.registros;
    const candidato =
      entidade.atributos.find((a) => a.nome === 'id') ??
      entidade.atributos.find((a) => (a.nome === 'codigo' || a.nome === 'code') && valoresUnicos(registros, a.nome));
    if (candidato) {
      candidato.marca = 'PK';
      chaves.set(entidade.nome, { atributo: candidato.nome, valores: new Set(registros.map((r) => r[candidato.nome])) });
    }
  }

  // 5. Referências: pelo nome (`<x>Id`, `<x>Ids`) e pelos valores (todos existem na chave de outra entidade).
  const porNomeMinusculo = new Map([...prontas.keys()].map((nome) => [nome.toLowerCase(), nome]));
  for (const entidade of prontas.values()) {
    const registros = entidades.get(entidade.nome)!.registros;
    for (const atributo of entidade.atributos) {
      if (atributo.marca === 'PK') {
        continue;
      }
      const valores = registros
        .flatMap((r) => (Array.isArray(r[atributo.nome]) ? (r[atributo.nome] as unknown[]) : [r[atributo.nome]]))
        .filter((v) => v !== null && v !== undefined);

      const pelaRegra = destinoPeloNome(atributo.nome, porNomeMinusculo);
      if (pelaRegra) {
        const chave = chaves.get(pelaRegra.destino);
        const confirmada = !!chave && valores.length > 0 && valores.every((v) => chave.valores.has(v));
        relacionamentos.push({
          de: entidade.nome,
          para: pelaRegra.destino,
          cardinalidade: pelaRegra.lista ? 'N:N' : 'N:1',
          regra: pelaRegra.lista ? 'listaDeReferencias' : 'referencia',
          campo: atributo.nome,
          confianca: confirmada ? 'alta' : 'baixa',
        });
        atributo.marca = 'FK';
        continue;
      }

      // Pelos valores: só texto, para números pequenos não casarem por acaso.
      if (!valores.length || !valores.every((v) => typeof v === 'string')) {
        continue;
      }
      const destino = [...chaves.entries()].find(
        ([nome, chave]) => nome !== entidade.nome && valores.every((v) => chave.valores.has(v)),
      );
      if (destino) {
        relacionamentos.push({
          de: entidade.nome,
          para: destino[0],
          cardinalidade: atributo.lista ? 'N:N' : 'N:1',
          regra: atributo.lista ? 'listaDeReferencias' : 'referencia',
          campo: atributo.nome,
          confianca: 'alta',
        });
        atributo.marca = 'FK';
      }
    }
  }

  // 6. Agrupamentos: listas guardadas pela chave de outra entidade (ex.: almoxarifados por filial).
  for (const grupo of agrupamentos) {
    const destino = [...chaves.entries()].find(
      ([nome, chave]) => nome !== grupo.entidade && grupo.chaves.every((c) => chave.valores.has(c)),
    );
    if (destino) {
      relacionamentos.push({
        de: destino[0],
        para: grupo.entidade,
        cardinalidade: '1:N',
        regra: 'agrupamento',
        campo: grupo.campo,
        confianca: 'alta',
      });
    }
  }

  const unicos = new Map(relacionamentos.map((r) => [`${r.de}|${r.para}|${r.regra}|${r.campo}`, r]));
  return {
    entidades: [...prontas.values()].sort((a, b) => a.nome.localeCompare(b.nome)),
    relacionamentos: [...unicos.values()].sort((a, b) =>
      `${a.de}|${a.para}|${a.campo}`.localeCompare(`${b.de}|${b.para}|${b.campo}`),
    ),
    avisos: [...telas.avisos, ...avisos],
  };
}

// ---------- Campos de uma entidade ----------

interface CampoDaEntidade {
  nome: string;
  forma: 'simples' | 'listaSimples' | 'objeto' | 'listaDeObjetos' | 'ignorar';
  tiposDeclarados: TipoObservado[];
  opcional: boolean;
  /** Tipo declarado do campo (sem nulo); null quando só há dados. */
  tipo: Type | null;
}

/** Campos pela declaração do tipo; sem tipo, pelas chaves que aparecem nos registros. */
function camposDe(entidade: EntidadeEmMontagem): CampoDaEntidade[] {
  if (entidade.tipo && entidade.local) {
    return entidade.tipo.getProperties().map((propriedade) => {
      const tipoCompleto = propriedade.getTypeAtLocation(entidade.local!);
      const opcional =
        propriedade.hasFlags(ts.SymbolFlags.Optional) ||
        (tipoCompleto.isUnion() && tipoCompleto.getUnionTypes().some((t) => t.isNull() || t.isUndefined()));
      const tipo = semNulos(tipoCompleto);
      return { nome: propriedade.getName(), opcional, tipo, ...classificar(tipo) };
    });
  }
  const nomes = [...new Set(entidade.registros.flatMap((registro) => Object.keys(registro)))];
  return nomes.map((nome) => ({ nome, forma: 'simples', tiposDeclarados: [], opcional: false, tipo: null }));
}

function classificar(tipo: Type): Pick<CampoDaEntidade, 'forma' | 'tiposDeclarados'> {
  const primitivos = tiposPrimitivos(tipo);
  if (primitivos) {
    return { forma: 'simples', tiposDeclarados: primitivos };
  }
  if (tipo.isArray()) {
    const item = semNulos(tipo.getArrayElementTypeOrThrow());
    const doItem = tiposPrimitivos(item);
    if (doItem) {
      return { forma: 'listaSimples', tiposDeclarados: doItem };
    }
    return ehObjetoDeDados(item) ? { forma: 'listaDeObjetos', tiposDeclarados: [] } : { forma: 'ignorar', tiposDeclarados: [] };
  }
  return ehObjetoDeDados(tipo) ? { forma: 'objeto', tiposDeclarados: [] } : { forma: 'ignorar', tiposDeclarados: [] };
}

/** texto, número, booleano, data, uniões de literais e enums; null para o resto. */
function tiposPrimitivos(tipo: Type): TipoObservado[] | null {
  const membros = tipo.isUnion() && !tipo.isBoolean() ? tipo.getUnionTypes() : [tipo];
  const tipos = new Set<TipoObservado>();
  for (const membro of membros) {
    if (membro.isNull() || membro.isUndefined()) continue;
    if (membro.isString() || membro.isStringLiteral() || membro.isTemplateLiteral()) tipos.add('texto');
    else if (membro.isNumber() || membro.isNumberLiteral()) tipos.add('numero');
    else if (membro.isBoolean() || membro.isBooleanLiteral()) tipos.add('booleano');
    else if (membro.getSymbol()?.getName() === 'Date') tipos.add('data');
    else if (membro.isEnumLiteral() || membro.isEnum()) tipos.add(typeof membro.getLiteralValue() === 'number' ? 'numero' : 'texto');
    else return null;
  }
  return [...tipos];
}

/** Objeto com propriedades de dado: sem métodos, sem ser lista, função ou dicionário livre. */
function ehObjetoDeDados(tipo: Type): boolean {
  if (!tipo.isObject() || tipo.isArray() || tipo.getCallSignatures().length > 0) {
    return false;
  }
  const propriedades = tipo.getProperties();
  return (
    propriedades.length > 0 &&
    !propriedades.some((p) => p.getDeclarations().some((d) => Node.isMethodDeclaration(d) || Node.isMethodSignature(d)))
  );
}

/** Entidade para objetos aninhados sem tipo com nome: uma existente com 80% dos atributos, ou `<Pai>.<campo>`. */
function entidadeParaObjetos(
  pai: string,
  campo: string,
  objetos: Registro[],
  tipo: Type | null,
  local: Node | null,
  entidades: Map<string, EntidadeEmMontagem>,
  prontas: Map<string, Entidade>,
): EntidadeEmMontagem {
  const chaves = tipo && local
    ? tipo.getProperties().map((p) => p.getName())
    : [...new Set(objetos.flatMap((o) => Object.keys(o)))];
  for (const existente of prontas.values()) {
    const nomes = new Set(existente.atributos.map((a) => a.nome));
    const comuns = chaves.filter((c) => nomes.has(c)).length;
    if (chaves.length && comuns / Math.max(chaves.length, nomes.size) >= SEMELHANCA_MINIMA) {
      return entidades.get(existente.nome)!;
    }
  }
  const nome = `${pai}.${campo}`;
  let entidade = entidades.get(nome);
  if (!entidade) {
    entidade = { nome, origens: [], tipo: tipo && local ? tipo : null, local: tipo && local ? local : null, registros: [] };
    entidades.set(nome, entidade);
  }
  return entidade;
}

// ---------- Utilitários ----------

function semNulos(tipo: Type): Type {
  if (!tipo.isUnion()) return tipo;
  const resto = tipo.getUnionTypes().filter((t) => !t.isNull() && !t.isUndefined());
  return resto.length === 1 ? resto[0] : tipo;
}

/** Tira nulo, Observable, Promise e lista, até chegar no tipo do dado. */
function desembrulhar(tipo: Type): Type {
  const t = semNulos(tipo);
  const nome = t.getAliasSymbol()?.getName() ?? t.getSymbol()?.getName();
  const argumento = t.getTypeArguments()[0] ?? t.getAliasTypeArguments()[0];
  if ((nome === 'Observable' || nome === 'Promise' || nome === 'ReadonlyArray') && argumento) {
    return desembrulhar(argumento);
  }
  if (t.isArray()) {
    return desembrulhar(t.getArrayElementTypeOrThrow());
  }
  return t;
}

function herdaDeErro(tipo: Type): boolean {
  return tipo.getBaseTypes().some((base) => base.getSymbol()?.getName() === 'Error' || herdaDeErro(base));
}

function ehObjetoSimples(valor: unknown): valor is Registro {
  return typeof valor === 'object' && valor !== null && !Array.isArray(valor) && !(valor instanceof Date);
}

function listaDeObjetos(valor: unknown): Registro[] | null {
  return Array.isArray(valor) && valor.length > 0 && valor.every(ehObjetoSimples) ? (valor as Registro[]) : null;
}

function objetoDeListas(valor: unknown): Record<string, Registro[]> | null {
  if (!ehObjetoSimples(valor)) return null;
  const listas = Object.values(valor);
  return listas.length > 0 && listas.every((lista) => Array.isArray(lista) && lista.every(ehObjetoSimples)) && listas.some((l) => (l as unknown[]).length)
    ? (valor as Record<string, Registro[]>)
    : null;
}

function tipoObservado(valor: unknown): TipoObservado | null {
  if (valor instanceof Date) return 'data';
  if (typeof valor === 'string') return /^\d{4}-\d{2}-\d{2}(T[\d:.]+(Z|[+-]\d{2}:?\d{2})?)?$/.test(valor) ? 'data' : 'texto';
  if (typeof valor === 'number') return 'numero';
  if (typeof valor === 'boolean') return 'booleano';
  return null;
}

function resumirExemplo(valor: unknown): string {
  const texto = Array.isArray(valor) ? `[${valor.join(', ')}]` : valor instanceof Date ? valor.toISOString() : String(valor);
  return texto.length > TAMANHO_DO_EXEMPLO ? `${texto.slice(0, TAMANHO_DO_EXEMPLO - 1)}…` : texto;
}

function semRepetidos(registros: Registro[]): Registro[] {
  const vistos = new Set<string>();
  return registros.filter((registro) => {
    const chave = JSON.stringify(registro);
    if (vistos.has(chave)) return false;
    vistos.add(chave);
    return true;
  });
}

function valoresUnicos(registros: Registro[], atributo: string): boolean {
  const valores = registros.map((r) => r[atributo]);
  return valores.length > 0 && valores.every((v) => v !== null && v !== undefined) && new Set(valores).size === valores.length;
}

/** `<x>Id`, `<x>_id`, `id<X>` → referência; `<x>Ids`, `<x>_ids` → lista de referências. */
function destinoPeloNome(atributo: string, entidades: Map<string, string>): { destino: string; lista: boolean } | null {
  const regras: [RegExp, boolean][] = [
    [/^(.+)Ids$/, true],
    [/^(.+)_ids$/i, true],
    [/^(.+)Id$/, false],
    [/^(.+)_id$/i, false],
    [/^id([A-Z].*)$/, false],
  ];
  for (const [regra, lista] of regras) {
    const alvo = regra.exec(atributo)?.[1];
    const destino = alvo && entidades.get(alvo.toLowerCase());
    if (destino) return { destino, lista };
  }
  return null;
}

function nomePeloExport(nome: string): string {
  const semSufixo = nome.replace(/(_MOCKS|_MOCK|Mocks|Mock)$/, '');
  return semSufixo
    .toLowerCase()
    .split(/[_\s-]+/)
    .filter(Boolean)
    .map((parte) => parte[0].toUpperCase() + parte.slice(1))
    .join('') || nome;
}

/** Converte o padrão `mocks` da configuração (ex.: `src/app/telas/**\/*.mock.ts`) num teste pelo nome do arquivo. */
function criarTesteDeMock(padrao: string): (arquivo: string) => boolean {
  const nome = basename(padrao).replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*');
  const regra = new RegExp(`^${nome}$`);
  return (arquivo) => regra.test(basename(arquivo));
}

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, relative, sep } from 'node:path';

import type { SchemaGerado, TagsGeradas } from '../modelo/tipos';
import type { ComponenteLido } from './componentes/ler-componentes';

const CABECALHO = '// ARQUIVO GERADO. Não edite.\n';

/** Só reescreve se o conteúdo mudou, para não provocar recarregamentos à toa. Devolve se escreveu. */
export function escreverSeMudou(caminho: string, conteudo: string): boolean {
  if (existsSync(caminho) && readFileSync(caminho, 'utf8') === conteudo) {
    return false;
  }
  mkdirSync(dirname(caminho), { recursive: true });
  writeFileSync(caminho, conteudo);
  return true;
}

/** Caminho de import de `alvo` (absoluto, sem extensão) a partir da pasta `de`. */
function caminhoDeImport(de: string, alvo: string): string {
  const caminho = relative(de, alvo).split(sep).join('/');
  return caminho.startsWith('.') ? caminho : `./${caminho}`;
}

const semExtensao = (caminho: string) => caminho.replace(/\.ts$/, '');

export function textoDosComponentes(
  componentes: ComponenteLido[],
  avisos: string[],
  raiz: string,
  saida: string,
  modelo: string,
): string {
  // As funções `carregar` e `ajuste` entram por marcadores, trocados por código depois do JSON.
  const codigo = new Map<string, string>();
  const dados = componentes.map(({ arquivoAjuste, ...componente }, indice) => {
    const marcadorCarregar = `@@carregar${indice}@@`;
    const marcadorAjuste = `@@ajuste${indice}@@`;
    const arquivo = caminhoDeImport(saida, semExtensao(`${raiz}/${componente.arquivo}`));
    codigo.set(marcadorCarregar, `() => import('${arquivo}').then((m) => m.${componente.classe})`);
    codigo.set(
      marcadorAjuste,
      arquivoAjuste
        ? `() => import('${caminhoDeImport(saida, semExtensao(`${raiz}/${arquivoAjuste}`))}').then((m) => m.default)`
        : 'null',
    );
    return { ...componente, carregar: marcadorCarregar, ajuste: marcadorAjuste };
  });

  let lista = JSON.stringify(dados, null, 2);
  for (const [marcador, trecho] of codigo) {
    lista = lista.replace(`"${marcador}"`, trecho);
  }
  return (
    CABECALHO +
    `import type { ComponenteRegistrado } from '${caminhoDeImport(saida, modelo)}';\n\n` +
    `export const AVISOS_DE_COMPONENTES: string[] = ${JSON.stringify(avisos, null, 2)};\n\n` +
    `export const COMPONENTES: ComponenteRegistrado[] = ${lista};\n`
  );
}

export function textoDoSchema(schema: SchemaGerado, saida: string, modelo: string): string {
  return (
    CABECALHO +
    `import type { SchemaGerado } from '${caminhoDeImport(saida, modelo)}';\n\n` +
    `export const SCHEMA: SchemaGerado = ${JSON.stringify(schema, null, 2)};\n`
  );
}

export function textoDasTags(tags: TagsGeradas, saida: string, modelo: string): string {
  return (
    CABECALHO +
    `import type { TagsGeradas } from '${caminhoDeImport(saida, modelo)}';\n\n` +
    `export const TAGS: TagsGeradas = ${JSON.stringify(tags, null, 2)};\n`
  );
}

import { join, resolve } from 'node:path';
import type { CompilerOptions } from 'ts-morph';

import type { SchemaGerado, TagsGeradas } from '../modelo/tipos';
import { LeituraDeComponentes, lerComponentes } from './componentes/ler-componentes';
import { lerDados } from './dados/ler-dados';
import { PASTA_PROTOTIPADOR, Telas, abrirTelas } from './projeto';
import { lerTags } from './traducoes/ler-tags';
import { Configuracao, lerConfiguracao } from './configuracao';
import { escreverSeMudou, textoDasTags, textoDoSchema, textoDosComponentes } from './escrita';

export interface OpcoesDeGeracao {
  /** Usada no lugar do prototipador.config.json da raiz. */
  configuracao?: Configuracao;
  /** Pasta dos arquivos gerados; padrão: src/app/prototipador/gerado. */
  saida?: string;
  /** Sobrepõe opções do tsconfig do projeto (ex.: onde achar node_modules). */
  opcoesDoCompilador?: CompilerOptions;
}

export interface Resumo {
  componentes: number;
  entidades: number;
  tags: number;
  avisos: number;
  milissegundos: number;
  /** Arquivos gerados que mudaram nesta geração. */
  alterados: string[];
}

export function gerar(raiz: string, opcoes: OpcoesDeGeracao = {}): Resumo {
  const inicio = performance.now();
  const configuracao = opcoes.configuracao ?? lerConfiguracao(raiz);
  const pastaDoPrototipador = resolve(raiz, PASTA_PROTOTIPADOR);
  const saida = opcoes.saida ?? join(pastaDoPrototipador, 'gerado');
  const modelo = join(pastaDoPrototipador, 'modelo', 'tipos');

  // Nunca interrompe: uma falha inesperada vira aviso e os arquivos são escritos mesmo assim.
  const falha = (parte: string, erro: unknown) => `Falha inesperada ao ler ${parte}: ${(erro as Error).stack ?? erro}`;
  let telas: Telas;
  try {
    telas = abrirTelas(raiz, configuracao, opcoes.opcoesDoCompilador);
  } catch (erro) {
    telas = { projeto: null!, arquivos: [], avisos: [falha('as telas', erro)] };
  }

  let leitura: LeituraDeComponentes;
  try {
    leitura = lerComponentes(raiz, configuracao, opcoes.opcoesDoCompilador, telas);
  } catch (erro) {
    leitura = { componentes: [], templates: [], avisos: [falha('os componentes', erro)] };
  }

  let schema: SchemaGerado;
  try {
    schema = lerDados(raiz, configuracao, telas);
  } catch (erro) {
    schema = { entidades: [], relacionamentos: [], avisos: [falha('os dados', erro)] };
  }

  let tags: TagsGeradas;
  try {
    tags = lerTags(raiz, configuracao, telas, leitura);
  } catch (erro) {
    tags = { tags: [], dinamicas: [], planilhaDisponivel: false, avisos: [falha('as tags de tradução', erro)] };
  }

  const arquivos: [string, string][] = [
    ['componentes.gerado.ts', textoDosComponentes(leitura.componentes, leitura.avisos, raiz, saida, modelo)],
    ['schema.gerado.ts', textoDoSchema(schema, saida, modelo)],
    ['tags.gerado.ts', textoDasTags(tags, saida, modelo)],
  ];
  const alterados = arquivos.filter(([nome, texto]) => escreverSeMudou(join(saida, nome), texto)).map(([nome]) => nome);

  // Um arquivo com erro aparece nos avisos de componentes e de dados; conta uma vez só.
  const avisos = new Set([
    ...leitura.avisos,
    ...leitura.componentes.flatMap((componente) => componente.avisos.map((aviso) => `${componente.id}: ${aviso}`)),
    ...schema.avisos,
    ...tags.avisos,
  ]).size;

  return {
    componentes: leitura.componentes.length,
    entidades: schema.entidades.length,
    tags: tags.tags.length,
    avisos,
    milissegundos: Math.round(performance.now() - inicio),
    alterados,
  };
}

export function linhaDoResumo(resumo: Resumo): string {
  const alteracao = resumo.alterados.length ? `atualizado: ${resumo.alterados.join(', ')}` : 'sem alterações';
  return (
    `[proto] ${resumo.componentes} componentes · ${resumo.entidades} entidades · ` +
    `${resumo.tags} tags · ${resumo.avisos} avisos · ${resumo.milissegundos}ms (${alteracao})`
  );
}

import { Node, ts } from 'ts-morph';

/** Marca de expressão que não é feita só de literais. */
export const NAO_LITERAL = Symbol('não literal');

export function textoFixo(no: Node): string | undefined {
  if (Node.isStringLiteral(no) || Node.isNoSubstitutionTemplateLiteral(no)) {
    return no.getLiteralText();
  }
  return undefined;
}

/** Valor de uma expressão feita só de literais; NAO_LITERAL para qualquer outra coisa. */
export function valorLiteral(no: Node): unknown {
  if (Node.isAsExpression(no) || Node.isParenthesizedExpression(no) || Node.isSatisfiesExpression(no)) {
    return valorLiteral(no.getExpression());
  }
  const texto = textoFixo(no);
  if (texto !== undefined) {
    return texto;
  }
  if (Node.isNumericLiteral(no)) {
    return no.getLiteralValue();
  }
  if (Node.isPrefixUnaryExpression(no) && no.getOperatorToken() === ts.SyntaxKind.MinusToken) {
    const valor = valorLiteral(no.getOperand());
    return typeof valor === 'number' ? -valor : NAO_LITERAL;
  }
  if (Node.isTrueLiteral(no)) {
    return true;
  }
  if (Node.isFalseLiteral(no)) {
    return false;
  }
  if (Node.isNullLiteral(no)) {
    return null;
  }
  if (Node.isArrayLiteralExpression(no)) {
    const itens = no.getElements().map(valorLiteral);
    return itens.includes(NAO_LITERAL) ? NAO_LITERAL : itens;
  }
  if (Node.isObjectLiteralExpression(no)) {
    const objeto: Record<string, unknown> = {};
    for (const propriedade of no.getProperties()) {
      if (!Node.isPropertyAssignment(propriedade)) {
        return NAO_LITERAL;
      }
      const nome = propriedade.getNameNode();
      const chave = Node.isIdentifier(nome) ? nome.getText() : textoFixo(nome);
      const valor = valorLiteral(propriedade.getInitializerOrThrow());
      if (chave === undefined || valor === NAO_LITERAL) {
        return NAO_LITERAL;
      }
      objeto[chave] = valor;
    }
    return objeto;
  }
  return NAO_LITERAL;
}

// Ponto de entrada do gerador. Rode a partir da raiz do projeto:
//   tsx src/app/prototipador/gerador/main.ts             gera uma vez
//   tsx src/app/prototipador/gerador/main.ts --observar  gera a cada alteração
import { gerar, linhaDoResumo } from './gerar';
import { observar } from './observar';

const raiz = process.cwd();

try {
  if (process.argv.includes('--observar')) {
    observar(raiz, process.argv[1]);
  } else {
    console.log(linhaDoResumo(gerar(raiz)));
  }
} catch (erro) {
  console.error(`[proto] ${(erro as Error).message}`);
  process.exitCode = 1;
}

import { spawn } from 'node:child_process';
import { resolve } from 'node:path';
import chokidar from 'chokidar';

import { PASTA_PROTOTIPADOR } from './projeto';
import { ARQUIVO_CONFIGURACAO, lerConfiguracao } from './configuracao';

const ESPERA_MS = 300;

/**
 * Vigia telas, i18n, planilha e configuração. Após 300ms sem alterações, roda uma geração
 * completa num processo filho, para que os mocks sejam recarregados do zero.
 */
export function observar(raiz: string, arquivoPrincipal: string): void {
  const configuracao = lerConfiguracao(raiz);
  const alvos = [
    configuracao.pastaTelas,
    configuracao.i18n.pasta,
    configuracao.planilha.arquivo,
    ARQUIVO_CONFIGURACAO,
  ].map((alvo) => resolve(raiz, alvo));

  let espera: NodeJS.Timeout | undefined;
  let rodando = false;
  let pendente = false;

  const rodar = (): void => {
    if (rodando) {
      pendente = true;
      return;
    }
    rodando = true;
    // process.execArgv traz o carregador do tsx, então o filho roda o mesmo main.ts.
    const filho = spawn(process.execPath, [...process.execArgv, arquivoPrincipal], { cwd: raiz, stdio: 'inherit' });
    filho.on('exit', () => {
      rodando = false;
      if (pendente) {
        pendente = false;
        rodar();
      }
    });
  };

  chokidar
    .watch(alvos, {
      ignoreInitial: true,
      ignored: (caminho: string) => resolve(caminho).startsWith(resolve(raiz, PASTA_PROTOTIPADOR)),
    })
    .on('all', () => {
      clearTimeout(espera);
      espera = setTimeout(rodar, ESPERA_MS);
    });

  console.log(`[proto] observando ${alvos.length} caminhos; gera de novo a cada alteração.`);
}

import { existsSync } from 'node:fs';
import { join, relative, resolve, sep } from 'node:path';
import { CompilerOptions, Project, SourceFile, ts } from 'ts-morph';

import type { Configuracao } from './configuracao';

/** Pasta do prototipador, relativa à raiz. Nunca é lida, mesmo que esteja dentro de pastaTelas. */
export const PASTA_PROTOTIPADOR = 'src/app/prototipador';

/** Arquivos das telas já carregados no verificador de tipos, prontos para os leitores. */
export interface Telas {
  projeto: Project;
  /** Arquivos sem erro de sintaxe, ordenados pelo caminho. */
  arquivos: SourceFile[];
  /** Arquivos que não puderam ser lidos. */
  avisos: string[];
}

export const posix = (caminho: string) => caminho.split(sep).join('/');

/** Abre `pastaTelas` (e os mocks fora dela) num projeto do ts-morph. Uma vez por geração. */
export function abrirTelas(raiz: string, config: Configuracao, opcoesDoCompilador: CompilerOptions = {}): Telas {
  const projeto = criarProjeto(raiz, opcoesDoCompilador);
  const pastaTelas = resolve(raiz, config.pastaTelas);
  if (!existsSync(pastaTelas)) {
    return { projeto, arquivos: [], avisos: [`pastaTelas "${config.pastaTelas}" não existe.`] };
  }
  projeto.addSourceFilesAtPaths([
    `${posix(pastaTelas)}/**/*.ts`,
    posix(resolve(raiz, config.mocks)),
    `!${posix(pastaTelas)}/**/*.spec.ts`,
    `!${posix(pastaTelas)}/**/*.proto.ts`,
    `!${posix(pastaTelas)}/**/*.d.ts`,
    `!${posix(resolve(raiz, PASTA_PROTOTIPADOR))}/**`,
  ]);

  const programa = projeto.getProgram().compilerObject;
  const avisos: string[] = [];
  const arquivos = [...projeto.getSourceFiles()]
    .sort((a, b) => (a.getFilePath() < b.getFilePath() ? -1 : 1))
    .filter((arquivo) => {
      const erro = programa.getSyntacticDiagnostics(arquivo.compilerNode)[0];
      if (!erro) {
        return true;
      }
      const linha = erro.start === undefined ? '?' : arquivo.getLineAndColumnAtPos(erro.start).line;
      const mensagem = typeof erro.messageText === 'string' ? erro.messageText : erro.messageText.messageText;
      avisos.push(`${posix(relative(raiz, arquivo.getFilePath()))}: erro de sintaxe na linha ${linha} (${mensagem}). Arquivo ignorado.`);
      return false;
    });
  return { projeto, arquivos, avisos };
}

function criarProjeto(raiz: string, opcoesDoCompilador: CompilerOptions): Project {
  const tsconfig = join(raiz, 'tsconfig.json');
  // O TypeScript do ts-morph é mais novo que o do projeto; opções antigas do tsconfig só geram aviso de obsoleto.
  const compilerOptions: CompilerOptions = { ignoreDeprecations: '6.0', noEmit: true, ...opcoesDoCompilador };
  if (existsSync(tsconfig)) {
    return new Project({ tsConfigFilePath: tsconfig, skipAddingFilesFromTsConfig: true, compilerOptions });
  }
  return new Project({
    compilerOptions: { strict: true, experimentalDecorators: true, target: ts.ScriptTarget.ES2022, ...compilerOptions },
  });
}

// Testes 1, 2 e 3 de docs/prototipador/05-gerador.md, sobre o mini-projeto em ./exemplos.
import assert from 'node:assert/strict';
import { join } from 'node:path';
