    const resultado = lerDados(raiz, config, abrirTelas(raiz, config));
    assert.deepEqual(resultado.entidades.map((e) => e.nome), ['Ponto']);
    assert.match(resultado.avisos[0], /telas\/quebrado\.ts: erro de sintaxe/);
  });
});

