    this.traducao.get(['ts.lista.a', 'ts.lista.b']).subscribe();
    this.traducao.stream('ts.stream').subscribe();
  }

  dinamica(sufixo: string): string {
    return this.traducao.instant('ts.' + sufixo);
  }
}

