// Testes 5 e 6 de docs/prototipador/05-gerador.md: tags de tradução e planilha.
import assert from 'node:assert/strict';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { after, describe, it } from 'node:test';

import type { TagUsada, UsoDeTag } from '../../modelo/tipos';
import { lerComponentes } from '../componentes/ler-componentes';
import { lerConfiguracao } from '../configuracao';
import { abrirTelas } from '../projeto';
import { lerTags } from '../traducoes/ler-tags';
import { lerPlanilha } from '../traducoes/planilha';

const EXEMPLOS = join(__dirname, 'exemplos');
const configuracao = lerConfiguracao(EXEMPLOS);
const telas = abrirTelas(EXEMPLOS, configuracao);
const resultado = lerTags(EXEMPLOS, configuracao, telas, lerComponentes(EXEMPLOS, configuracao, {}, telas));

function tag(chave: string): TagUsada {
  const achada = resultado.tags.find((t) => t.chave === chave);
  assert.ok(achada, `tag "${chave}" não encontrada`);
  return achada;
}

const uso = (chave: string): UsoDeTag => tag(chave).usos[0];

describe('teste 5: tags no template', () => {
  it('pipe com texto fixo: chave, três textos, componente e contexto', () => {
    const titulo = tag('tela.titulo');
    assert.deepEqual(titulo.textos, { pt: 'Título', en: 'Title', es: 'Título' });
    assert.deepEqual(uso('tela.titulo'), {
      componente: 'ex-textos',
      arquivo: 'telas/traducoes/textos.component.html',
      linha: 1,
      papel: 'título',
      condicao: null,
      trecho: "<h2>{{ 'tela.titulo' | translate }}</h2>",
      provavel: false,
    });
  });

  it('pipe com parâmetros', () => {
    assert.equal(uso('tela.ola').linha, 2);
  });

  it('chaves aninhadas nos arquivos i18n viram caminhos com ponto; texto ausente fica de fora', () => {
    assert.deepEqual(tag('link.ajuda').textos, { pt: 'Ajuda', en: 'Help' });
    assert.deepEqual(tag('codigo.provavel').textos, { pt: 'Código', en: 'Code', es: 'Código' });
  });

  const papeis: [string, string][] = [
    ['acao.salvar', 'rótulo do botão'],
    ['acao.cancelar', 'rótulo do botão'],
    ['campo.nome', 'rótulo de campo'],
    ['tela.titulo', 'título'],
    ['coluna.codigo', 'cabeçalho de coluna'],
    ['link.ajuda', 'link'],
    ['campo.dica', 'placeholder do campo'],
    ['dica.texto', 'tooltip'],
    ['aba.geral', 'título de p-tabPanel'],
    ['acao.fechar', 'rótulo acessível'],
    ['lista.semopcoes', 'propriedade emptyMessage de p-dropdown'],
    ['tela.ola', 'texto em p'],
  ];
  for (const [chave, papel] of papeis) {
    it(`papel: ${papel}`, () => assert.equal(uso(chave).papel, papel));
  }

  it('diretiva: conteúdo e chave vinculada', () => {
    assert.equal(uso('diretiva.conteudo').papel, 'texto em span');
    assert.equal(uso('diretiva.vinculada').papel, 'texto em span');
  });

  const condicoes: [string, string][] = [
    ['lista.vazia', 'aparece quando: `itens.length === 0`'],
    ['lista.cheia', 'senão de: `itens.length === 0`'],
    ['lista.nada', 'lista vazia de: `itens`'],
    ['modo.a', "aparece quando: `modo === 'a'`"],
    ['modo.outro', 'senão de: `modo` (nenhum caso)'],
    ['estrutural.texto', 'aparece quando: `mostrar`'],
  ];
  for (const [chave, condicao] of condicoes) {
    it(`condição: ${condicao}`, () => assert.equal(uso(chave).condicao, condicao));
  }

  it('chave usada em dois componentes: uma tag, dois usos', () => {
    assert.deepEqual(tag('acao.salvar').usos.map((u) => [u.componente, u.arquivo, u.linha]), [
      ['ex-textos', 'telas/traducoes/textos.component.html', 3],
      ['ex-textos-em-linha', 'telas/traducoes/textos-em-linha.component.ts', 8],
    ]);
  });

  it('ternário entre textos fixos conta as duas chaves', () => {
    assert.equal(uso('estado.ativo').linha, 36);
    assert.equal(uso('estado.inativo').linha, 36);
  });

  it('chaves montadas no template vão para as dinâmicas', () => {
    const doTemplate = resultado.dinamicas.filter((d) => d.arquivo.endsWith('.html')).map((d) => d.expressao);
    assert.deepEqual(doTemplate, ["'status.' + estado", 'coluna.header']);
  });
});

describe('teste 5: tags no código', () => {
  it('mensagem de aviso (toast)', () => assert.equal(uso('ts.toast').papel, 'mensagem de aviso (toast) · summary'));
  it('diálogo de confirmação', () => assert.equal(uso('ts.confirmacao').papel, 'diálogo de confirmação · message'));
  it('outra chamada: texto montado no código, com o método', () => assert.equal(uso('ts.montado').papel, 'texto montado no código, em montar()'));
  it('get com lista de chaves e stream', () => {
    assert.equal(uso('ts.lista.a').linha, 39);
    assert.equal(uso('ts.lista.b').linha, 39);
    assert.equal(uso('ts.stream').linha, 40);
  });
  it('chave montada no código vai para as dinâmicas', () => {
    const doCodigo = resultado.dinamicas.find((d) => d.arquivo.endsWith('.ts'));
    assert.deepEqual([doCodigo?.expressao, doCodigo?.papel], ["'ts.' + sufixo", 'texto montado no código, em dinamica()']);
  });
  it('uso provável: texto fixo igual a uma chave dos arquivos i18n', () => {
    assert.deepEqual([uso('codigo.provavel').papel, uso('codigo.provavel').provavel], ['texto no código (uso provável)', true]);
    assert.ok(!resultado.tags.some((t) => t.chave === 'texto qualquer'));
  });
});

describe('teste 6: planilha', () => {
  it('Existente quando a chave está na planilha (sem espaços nas pontas), Nova quando não está', () => {
    assert.equal(resultado.planilhaDisponivel, true);
    assert.equal(tag('acao.salvar').naPlanilha, true);
    assert.equal(tag('acao.cancelar').naPlanilha, true);
    assert.equal(tag('campo.nome').naPlanilha, false);
  });

  const pasta = mkdtempSync(join(tmpdir(), 'proto-planilha-'));
  after(() => rmSync(pasta, { recursive: true, force: true }));
  const arquivo = (nome: string, conteudo: string) => {
    const caminho = join(pasta, nome);
    writeFileSync(caminho, conteudo);
    return caminho;
  };

  it('CSV com vírgula', () => {
    const lida = lerPlanilha(arquivo('virgula.csv', 'Tag,PT\na.b,Um\n"c,d",Dois\n'), 'Tag', 'virgula.csv');
    assert.deepEqual([lida.disponivel, [...lida.chaves]], [true, ['a.b', 'c,d']]);
  });

  it('CSV com ponto e vírgula e marca de ordem de bytes', () => {
    const lida = lerPlanilha(arquivo('ponto.csv', '﻿Chave;Texto\nx.y;Um\nz;Dois\n'), 'Chave', 'ponto.csv');
    assert.deepEqual([lida.disponivel, [...lida.chaves]], [true, ['x.y', 'z']]);
  });

  it('cabeçalho depois de linhas de informação', () => {
    const lida = lerPlanilha(arquivo('info.csv', 'atualizado em,,\n,,\nTag,PT,EN\nk1,a,b\n'), 'Tag', 'info.csv');
    assert.deepEqual([...lida.chaves], ['k1']);
  });

  it('coluna não encontrada: indisponível, com os cabeçalhos no aviso', () => {
    const lida = lerPlanilha(arquivo('sem.csv', 'Chave,PT\na,b\n'), 'Tag', 'sem.csv');
    assert.equal(lida.disponivel, false);
    assert.match(lida.aviso ?? '', /"Tag" não foi encontrada.*Cabeçalhos encontrados: Chave, PT/);
  });

  it('arquivo que não existe', () => {
    const lida = lerPlanilha(join(pasta, 'nao-existe.csv'), 'Tag', 'entrada/tags.csv');
    assert.equal(lida.disponivel, false);
    assert.match(lida.aviso ?? '', /não encontrada em "entrada\/tags\.csv"/);
  });
});

import { readFileSync } from 'node:fs';
import { relative, resolve } from 'node:path';
import { CallExpression, NoSubstitutionTemplateLiteral, Node, StringLiteral } from 'ts-morph';

import type { ChaveDinamica, TagUsada, TagsGeradas, UsoDeTag } from '../../modelo/tipos';
import type { LeituraDeComponentes } from '../componentes/ler-componentes';
import { lerTagsDoTemplate } from '../componentes/template';
import type { Configuracao } from '../configuracao';
import { Telas, posix } from '../projeto';
import { lerPlanilha } from './planilha';

/** Ver docs/prototipador/04-traducoes.md e 05-gerador.md, "Leitura das tags". */

const TAMANHO_DO_TRECHO = 160;
const METODOS_DE_TRADUCAO = new Set(['instant', 'get', 'stream']);
const PAPEL_PROVAVEL = 'texto no código (uso provável)';

type Idioma = 'pt' | 'en' | 'es';

export function lerTags(raiz: string, config: Configuracao, telas: Telas, componentes: LeituraDeComponentes): TagsGeradas {
  const avisos: string[] = [];
  const usos = new Map<string, UsoDeTag[]>();
  const dinamicas: ChaveDinamica[] = [];
  const caminho = (absoluto: string) => posix(relative(raiz, absoluto));
  const linhasDe = memorizar((absoluto: string) => readFileSync(absoluto, 'utf8').split(/\r?\n/));
  const trecho = (absoluto: string, linha: number) => (linhasDe(absoluto)[linha - 1] ?? '').trim().slice(0, TAMANHO_DO_TRECHO);
  const adicionar = (chave: string, uso: UsoDeTag) => usos.set(chave, [...(usos.get(chave) ?? []), uso]);

  // Textos dos arquivos i18n, com chaves aninhadas achatadas em caminhos com ponto.
  const textos: Record<Idioma, Map<string, string>> = { pt: new Map(), en: new Map(), es: new Map() };
  for (const idioma of ['pt', 'en', 'es'] as const) {
    const nome = config.i18n.idiomas[idioma];
    if (!nome) {
      avisos.push(`i18n.idiomas não define o arquivo de "${idioma}".`);
      continue;
    }
    const arquivo = resolve(raiz, config.i18n.pasta, nome);
    try {
      achatar(JSON.parse(readFileSync(arquivo, 'utf8')), '', textos[idioma]);
    } catch (erro) {
      avisos.push(`${caminho(arquivo)}: não foi possível ler (${(erro as Error).message}).`);
    }
  }
  const chavesDosArquivos = new Set([...textos.pt.keys(), ...textos.en.keys(), ...textos.es.keys()]);

  // 1. Templates
  for (const template of componentes.templates) {
    let lidos;
    try {
      lidos = lerTagsDoTemplate(template.texto, template.arquivo, config.traducao.pipe);
    } catch (erro) {
      avisos.push(`${caminho(template.arquivo)}: não foi possível ler as tags do template (${(erro as Error).message}).`);
      continue;
    }
    for (const lido of lidos) {
      const linha = template.linhaInicial + lido.linha + 1;
      const base = { componente: template.id, arquivo: caminho(template.arquivo), linha, papel: lido.papel, condicao: lido.condicao, trecho: trecho(template.arquivo, linha) };
      if (lido.chave === null) {
        dinamicas.push({ ...base, expressao: lido.expressao });
      } else {
        adicionar(lido.chave, { ...base, provavel: false });
      }
    }
  }

  // 2. Código: chamadas ao serviço de tradução e textos fixos idênticos a uma chave.
  const componentesPorArquivo = new Map<string, { id: string; classe: string }[]>();
  for (const c of componentes.componentes) {
    // Mesma forma de caminho do ts-morph (barras normais), para casar com getFilePath().
    const absoluto = posix(resolve(raiz, c.arquivo));
    componentesPorArquivo.set(absoluto, [...(componentesPorArquivo.get(absoluto) ?? []), { id: c.id, classe: c.classe }]);
  }
  const quemUsa = criarBuscaDeComponentes(componentesPorArquivo);

  for (const arquivo of telas.arquivos) {
    const absoluto = arquivo.getFilePath();
    const jaLidos = new Set<number>();

    for (const chamada of arquivo.getDescendants().filter(Node.isCallExpression)) {
      if (!ehChamadaDeTraducao(chamada, config.traducao.servico)) continue;
      const argumento = chamada.getArguments()[0];
      if (!argumento) continue;
      const fixas = textosFixos(argumento);
      const linha = argumento.getStartLineNumber();
      const papel = papelNoCodigo(chamada);
      for (const componente of quemUsa(chamada)) {
        const base = { componente, arquivo: caminho(absoluto), linha, papel, condicao: null, trecho: trecho(absoluto, linha) };
        if (fixas) {
          fixas.forEach(({ chave }) => adicionar(chave, { ...base, provavel: false }));
        } else {
          dinamicas.push({ ...base, expressao: argumento.getText() });
        }
      }
      fixas?.forEach(({ no }) => jaLidos.add(no.getStart()));
    }

    // Uso provável: qualquer texto fixo do código igual a uma chave dos arquivos i18n.
    for (const literal of arquivo.getDescendants().filter(ehTextoFixo)) {
      const chave = literal.getLiteralText();
      if (!chavesDosArquivos.has(chave) || jaLidos.has(literal.getStart())) continue;
      const linha = literal.getStartLineNumber();
      for (const componente of quemUsa(literal)) {
        adicionar(chave, { componente, arquivo: caminho(absoluto), linha, papel: PAPEL_PROVAVEL, condicao: null, trecho: trecho(absoluto, linha), provavel: true });
      }
    }
  }

  // 3. Planilha
  const planilha = lerPlanilha(resolve(raiz, config.planilha.arquivo), config.planilha.colunaChave, config.planilha.arquivo);
  if (planilha.aviso) avisos.push(planilha.aviso);

  const ordenarUsos = (a: UsoDeTag, b: UsoDeTag) =>
    a.componente.localeCompare(b.componente) || a.arquivo.localeCompare(b.arquivo) || a.linha - b.linha || a.papel.localeCompare(b.papel);
  const tags: TagUsada[] = [...usos.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([chave, lista]) => ({
      chave,
      textos: Object.fromEntries((['pt', 'en', 'es'] as const).filter((i) => textos[i].has(chave)).map((i) => [i, textos[i].get(chave)!])),
      naPlanilha: planilha.disponivel ? planilha.chaves.has(chave) : null,
      usos: semRepetir(lista).sort(ordenarUsos),
    }));

  return {
    tags,
    dinamicas: dinamicas.sort((a, b) => a.componente.localeCompare(b.componente) || a.arquivo.localeCompare(b.arquivo) || a.linha - b.linha),
    planilhaDisponivel: planilha.disponivel,
    avisos,
  };
}

// ---------- Código TypeScript ----------

/** `x.instant(...)`, `x.get(...)` ou `x.stream(...)` num objeto do tipo do serviço de tradução. */
function ehChamadaDeTraducao(chamada: CallExpression, servico: string): boolean {
  const expressao = chamada.getExpression();
  if (!Node.isPropertyAccessExpression(expressao) || !METODOS_DE_TRADUCAO.has(expressao.getName())) return false;
  const tipo = expressao.getExpression().getType();
  return (tipo.getSymbol() ?? tipo.getAliasSymbol())?.getName() === servico;
}

/** Texto fixo ou lista de textos fixos; null quando a chave é montada no código. */
function textosFixos(argumento: Node): { chave: string; no: Node }[] | null {
  if (ehTextoFixo(argumento)) {
    return [{ chave: argumento.getLiteralText(), no: argumento }];
  }
  if (Node.isArrayLiteralExpression(argumento)) {
    const itens = argumento.getElements();
    if (itens.every(ehTextoFixo)) {
      return itens.map((i) => ({ chave: i.getLiteralText(), no: i }));
    }
  }
  return null;
}

function ehTextoFixo(no: Node): no is StringLiteral | NoSubstitutionTemplateLiteral {
  return Node.isStringLiteral(no) || Node.isNoSubstitutionTemplateLiteral(no);
}

/** Aviso (toast), diálogo de confirmação ou texto montado no código, com a propriedade quando houver. */
function papelNoCodigo(no: Node): string {
  let propriedade: string | null = null;
  for (let atual: Node | undefined = no.getParent(); atual; atual = atual.getParent()) {
    if (!propriedade && Node.isPropertyAssignment(atual)) propriedade = atual.getName();
    if (Node.isCallExpression(atual)) {
      const chamada = atual.getExpression();
      if (Node.isPropertyAccessExpression(chamada)) {
        const tipo = chamada.getExpression().getType().getSymbol()?.getName();
        if (chamada.getName() === 'add' && tipo === 'MessageService') return comPropriedade('mensagem de aviso (toast)', propriedade);
        if (chamada.getName() === 'confirm' && tipo === 'ConfirmationService') return comPropriedade('diálogo de confirmação', propriedade);
      }
    }
    if (Node.isObjectLiteralExpression(atual)) {
      const contexto = atual.getContextualType()?.getSymbol()?.getName() ?? atual.getContextualType()?.getAliasSymbol()?.getName();
      if (contexto === 'Confirmation') return comPropriedade('diálogo de confirmação', propriedade);
      if (contexto === 'Message') return comPropriedade('mensagem de aviso (toast)', propriedade);
    }
    if (Node.isMethodDeclaration(atual) || Node.isFunctionDeclaration(atual) || Node.isGetAccessorDeclaration(atual)) {
      return `texto montado no código, em ${atual.getName() ?? '(anônimo)'}()`;
    }
  }
  return 'texto montado no código';
}

function comPropriedade(papel: string, propriedade: string | null): string {
  return propriedade ? `${papel} · ${propriedade}` : papel;
}

/**
 * Componentes a quem um trecho do código pertence: a classe do componente que o contém, ou,
 * fora de um componente (modelo, utilitário), os componentes que usam a declaração de topo.
 */
function criarBuscaDeComponentes(componentesPorArquivo: Map<string, { id: string; classe: string }[]>): (no: Node) => string[] {
  const cache = new Map<Node, string[]>();
  return (no) => {
    const arquivo = no.getSourceFile().getFilePath();
    const doArquivo = componentesPorArquivo.get(arquivo) ?? [];
    const classe = no.getFirstAncestor(Node.isClassDeclaration)?.getName();
    const daClasse = doArquivo.find((c) => c.classe === classe);
    if (daClasse) return [daClasse.id];
    if (doArquivo.length) return doArquivo.map((c) => c.id);

    const topo = declaracaoDeTopo(no);
    if (!topo) return [''];
    if (!cache.has(topo)) {
      const ids = componentesQueReferenciam(topo, new Set());
      cache.set(topo, ids.size ? [...ids].sort() : ['']);
    }
    return cache.get(topo)!;
  };

  /** Segue as referências: um utilitário usado por outro utilitário chega aos componentes deste. */
  function componentesQueReferenciam(topo: Node, visitados: Set<Node>): Set<string> {
    const ids = new Set<string>();
    if (visitados.has(topo)) return ids;
    visitados.add(topo);
    const nomeavel = Node.isVariableStatement(topo) ? topo.getDeclarations()[0] : topo;
    const referencias = Node.isReferenceFindable(nomeavel) ? nomeavel.findReferencesAsNodes() : [];
    for (const referencia of referencias) {
      const daReferencia = componentesPorArquivo.get(referencia.getSourceFile().getFilePath()) ?? [];
      if (daReferencia.length) {
        const classeDaReferencia = referencia.getFirstAncestor(Node.isClassDeclaration)?.getName();
        const exata = daReferencia.find((c) => c.classe === classeDaReferencia);
        (exata ? [exata] : daReferencia).forEach((c) => ids.add(c.id));
      } else {
        const outroTopo = declaracaoDeTopo(referencia);
        if (outroTopo && outroTopo !== topo) componentesQueReferenciam(outroTopo, visitados).forEach((id) => ids.add(id));
      }
    }
    return ids;
  }
}

function declaracaoDeTopo(no: Node): Node | undefined {
  let atual: Node | undefined = no;
  while (atual && !Node.isSourceFile(atual.getParent() ?? atual)) {
    atual = atual.getParent();
  }
  return atual && !Node.isSourceFile(atual) ? atual : undefined;
}

// ---------- Utilitários ----------

function achatar(valor: unknown, prefixo: string, destino: Map<string, string>): void {
  if (valor && typeof valor === 'object' && !Array.isArray(valor)) {
    for (const [chave, item] of Object.entries(valor)) {
      achatar(item, prefixo ? `${prefixo}.${chave}` : chave, destino);
    }
  } else if (prefixo && (typeof valor === 'string' || typeof valor === 'number')) {
    destino.set(prefixo, String(valor));
  }
}

function semRepetir(usos: UsoDeTag[]): UsoDeTag[] {
  const vistos = new Set<string>();
  return usos.filter((u) => {
    const chave = `${u.componente}|${u.arquivo}|${u.linha}|${u.papel}`;
    if (vistos.has(chave)) return false;
    vistos.add(chave);
    return true;
  });
}

function memorizar<T>(funcao: (chave: string) => T): (chave: string) => T {
  const cache = new Map<string, T>();
  return (chave) => {
    if (!cache.has(chave)) cache.set(chave, funcao(chave));
    return cache.get(chave)!;
  };
}

import { existsSync, readFileSync } from 'node:fs';
import { parse } from 'csv-parse/sync';

export interface LeituraDaPlanilha {
  disponivel: boolean;
  chaves: Set<string>;
  aviso: string | null;
}

/**
 * Lê as chaves da planilha de tags (CSV). Detecta o separador (`,` ou `;`) e ignora a marca de
 * ordem de bytes. O cabeçalho é a primeira linha que tem a coluna `colunaChave` (a planilha do
 * produto traz linhas de informação antes dele).
 */
export function lerPlanilha(caminho: string, colunaChave: string, nomeNaConfiguracao: string): LeituraDaPlanilha {
  const indisponivel = (aviso: string): LeituraDaPlanilha => ({ disponivel: false, chaves: new Set(), aviso });
  if (!existsSync(caminho)) {
    return indisponivel(`Planilha de tags não encontrada em "${nomeNaConfiguracao}". Exporte o CSV para esse caminho (planilha.arquivo no prototipador.config.json).`);
  }
  const texto = readFileSync(caminho, 'utf8').replace(/^﻿/, '');
  const coluna = colunaChave.trim();
  let primeiraLinha: string[] = [];

  for (const separador of [',', ';']) {
    let linhas: string[][];
    try {
      linhas = parse(texto, { delimiter: separador, relax_column_count: true, relax_quotes: true, skip_empty_lines: true });
    } catch {
      continue;
    }
    if (!primeiraLinha.length) {
      primeiraLinha = linhas.find((linha) => linha.some((celula) => celula.trim())) ?? [];
    }
    if (!coluna) {
      break;
    }
    const cabecalho = linhas.findIndex((linha) => linha.some((celula) => celula.trim() === coluna));
    if (cabecalho >= 0) {
      const indice = linhas[cabecalho].findIndex((celula) => celula.trim() === coluna);
      const chaves = new Set(linhas.slice(cabecalho + 1).map((linha) => (linha[indice] ?? '').trim()).filter(Boolean));
      return { disponivel: true, chaves, aviso: null };
    }
  }

  const encontrados = primeiraLinha.map((celula) => celula.trim()).filter(Boolean).join(', ') || '(nenhum)';
  return indisponivel(
    coluna
      ? `A coluna "${coluna}" não foi encontrada na planilha. Cabeçalhos encontrados: ${encontrados}. Ajuste planilha.colunaChave no prototipador.config.json.`
      : `planilha.colunaChave não está configurada no prototipador.config.json. Cabeçalhos encontrados: ${encontrados}.`,
  );
}

// Contrato entre o gerador (Node) e a interface (Angular).
// TypeScript puro: sem imports do Angular nem do Node.

// ---------- Componentes ----------

export type TipoCampo =
  | { tipo: 'texto' }
  | { tipo: 'numero' }
  | { tipo: 'booleano' }
  | { tipo: 'data' }
  | { tipo: 'opcoes'; valores: (string | number)[] }
  | { tipo: 'objeto'; campos: Campo[] }
  | { tipo: 'lista'; item: TipoCampo }
  | { tipo: 'naoEditavel'; textoDoTipo: string; motivo: string };

export interface Campo {
  nome: string;
  tipo: TipoCampo;
  opcional: boolean;      // pode ficar indefinido
  aceitaNulo: boolean;
}

export interface InputRegistrado extends Campo {
  // `nome` é o nome público (o alias, se houver): é o que se passa ao setInput
  propriedade: string;    // nome da propriedade na classe
  padrao?: unknown;       // só quando o valor inicial é um literal
}

export interface OutputRegistrado {
  nome: string;           // nome público
  propriedade: string;
}

export interface ComponenteRegistrado {
  id: string;             // o seletor; se não houver, o nome da classe
  seletor: string | null;
  classe: string;
  arquivo: string;        // caminho relativo à raiz do projeto
  pasta: string;          // relativa a pastaTelas; grupo padrão na área de teste
  standalone: boolean;
  inputs: InputRegistrado[];
  outputs: OutputRegistrado[];
  filhos: string[];       // ids dos componentes do projeto usados no template
  carregar: () => Promise<unknown>;        // devolve a classe do componente
  ajuste: (() => Promise<unknown>) | null; // devolve o export default do .proto.ts
  avisos: string[];
}

// ---------- Schema ----------

export type TipoObservado = 'texto' | 'numero' | 'booleano' | 'data';

export interface Atributo {
  nome: string;
  tipos: TipoObservado[];
  /** Lista de valores simples (ex.: `tipos: RepositoryType[]`). */
  lista?: boolean;
  opcional: boolean;
  exemplo: string | null;
  marca: 'PK' | 'FK' | null;
}

export interface Entidade {
  nome: string;
  origens: { arquivo: string; exportacao: string }[];
  registros: number;
  atributos: Atributo[];
}

export interface Relacionamento {
  de: string;
  para: string;
  cardinalidade: '1:1' | '1:N' | 'N:1' | 'N:N';
  // agrupamento: dados guardados por chave de outra entidade (ex.: almoxarifados por código da filial)
  regra: 'aninhado' | 'listaAninhada' | 'referencia' | 'listaDeReferencias' | 'agrupamento';
  campo: string;
  confianca: 'alta' | 'baixa';
}

export interface SchemaGerado {
  entidades: Entidade[];
  relacionamentos: Relacionamento[];
  avisos: string[];
}

// ---------- Tags ----------

export interface UsoDeTag {
  componente: string;     // id do componente
  arquivo: string;
  linha: number;
  papel: string;          // ex.: "rótulo do botão"
  condicao: string | null;
  trecho: string;
  provavel: boolean;      // true = texto fixo no .ts idêntico a uma chave
}

export interface TagUsada {
  chave: string;
  textos: { pt?: string; en?: string; es?: string };
  naPlanilha: boolean | null;   // null = planilha indisponível
  usos: UsoDeTag[];
}

export interface ChaveDinamica extends Omit<UsoDeTag, 'provavel'> {
  expressao: string;
}

export interface TagsGeradas {
  tags: TagUsada[];
  dinamicas: ChaveDinamica[];
  planilhaDisponivel: boolean;
  avisos: string[];
}

// Estado do prototipador guardado no localStorage, para sobreviver ao recarregamento.
// O acesso pode falhar (janela privada, armazenamento bloqueado): nesse caso vale o padrão.

export function ler<T>(chave: string, padrao: T): T {
  try {
    const bruto = localStorage.getItem(chave);
    return bruto === null ? padrao : (JSON.parse(bruto) as T);
  } catch {
    return padrao;
  }
}

export function gravar(chave: string, valor: unknown): void {
  try {
    localStorage.setItem(chave, JSON.stringify(valor));
  } catch {
    // Sem armazenamento, o estado vale só até recarregar.
  }
}

:host {
  box-sizing: border-box;
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  grid-template-rows: 56px minmax(0, 1fr);
  height: 100vh;
  padding: 0 16px 16px 0;
  overflow: hidden;
  background: #f1f2f4;
  transition: grid-template-columns 0.15s;
}

:host(.proto-moldura--aberta) {
  grid-template-columns: 200px minmax(0, 1fr);
}

.proto-topo {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* Centralizado sobre a coluna de ícones do menu. */
.proto-topo__alternar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  margin-left: 7px;
  padding: 0;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--text-color);
  cursor: pointer;
}

.proto-topo__alternar:hover {
  background: rgba(0, 0, 0, 0.04);
}

.proto-menu {
  overflow: hidden;
}

.proto-menu__lista {
  margin: 0;
  padding: 10px 0 0;
  list-style: none;
}

/* O ícone fica na mesma posição aberto ou fechado; aberto, o item cresce para o rótulo. */
.proto-menu__item {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 12px;
  width: 46px;
  height: 28px;
  margin-bottom: 15px;
  padding-left: 15px;
  border-radius: 0 6px 6px 0;
  color: var(--text-color);
  font-size: 0.875rem;
  text-decoration: none;
  white-space: nowrap;
}

:host(.proto-moldura--aberta) .proto-menu__item {
  width: calc(100% - 8px);
}

.proto-menu__item:hover {
  background: rgba(0, 0, 0, 0.04);
}

