import { Component, computed, inject, signal } from '@angular/core';
import { NgClass } from '@angular/common';
import { NavigationEnd, Router, RouterOutlet } from '@angular/router';
import { filter } from 'rxjs';

import { ExibirTagsService } from '../principal/exibir-tags.service';
import { SeletorIdiomaComponent } from '../principal/seletor-idioma.component';
import { gravar, ler } from './armazenamento';
import { TelaAtualService } from './tela-atual.service';

const CHAVE_MENU = 'proto.menuRecolhido';

interface ItemDoMenu {
  rotulo: string;
  icone: string;
  destino: string;
  ativo: boolean;
}

@Component({
  selector: 'proto-moldura',
  standalone: true,
  imports: [NgClass, RouterOutlet, SeletorIdiomaComponent],
  templateUrl: './moldura.component.html',
  styleUrl: './moldura.component.css',
  host: { '[class.proto-moldura--aberta]': '!recolhido()' },
})
export class MolduraComponent {
  private readonly router = inject(Router);
  private readonly telaAtual = inject(TelaAtualService);

  // Fechado (só ícones) por padrão, como no layout de referência.
  protected readonly recolhido = signal<boolean>(ler<unknown>(CHAVE_MENU, true) !== false);

  private readonly url = signal(this.router.url);

  protected readonly itens = computed<ItemDoMenu[]>(() => {
    const url = this.url();
    const naPrincipal = !url.startsWith('/_proto');
    return [
      { rotulo: 'Principal', icone: 'pi-desktop', destino: this.telaAtual.tela()?.url ?? '/', ativo: naPrincipal },
      { rotulo: 'Área de teste', icone: 'pi-box', destino: '/_proto/teste', ativo: url.startsWith('/_proto/teste') },
      { rotulo: 'Dados', icone: 'pi-sitemap', destino: '/_proto/dados', ativo: url.startsWith('/_proto/dados') },
      { rotulo: 'Traduções', icone: 'pi-language', destino: '/_proto/traducoes', ativo: url.startsWith('/_proto/traducoes') },
    ];
  });

  constructor() {
    // Criado aqui para que o idioma e o modo "exibir tags" guardados valham desde a primeira tela.
    inject(ExibirTagsService);
    this.router.events
      .pipe(filter((evento): evento is NavigationEnd => evento instanceof NavigationEnd))
      .subscribe((evento) => this.url.set(evento.urlAfterRedirects));
  }

  protected navegar(evento: MouseEvent, destino: string): void {
    // Deixa o navegador tratar ctrl+clique e afins (abrir em nova aba).
    if (evento.button !== 0 || evento.ctrlKey || evento.metaKey || evento.shiftKey) {
      return;
    }
    evento.preventDefault();
    this.router.navigateByUrl(destino).catch(() => {
      // A tela atual guardada pode não existir mais (rota removida ou renomeada): esquece e vai para o início.
      this.telaAtual.esquecer();
      this.router.navigateByUrl('/');
    });
  }

  protected alternarMenu(): void {
    this.recolhido.update((valor) => !valor);
    gravar(CHAVE_MENU, this.recolhido());
  }
}

import { Injectable, Type, inject, reflectComponentType, signal } from '@angular/core';
import { ActivatedRouteSnapshot, NavigationEnd, Router } from '@angular/router';
import { filter } from 'rxjs';

import { gravar, ler } from './armazenamento';

export interface TelaAtual {
  url: string;
  idsRaiz: string[];
}

const CHAVE = 'proto.telaAtual';

/** Mesma regra do campo `id` do registro de componentes: o seletor, ou o nome da classe. */
export function idDoComponente(componente: Type<unknown>): string {
  const seletor = reflectComponentType(componente)?.selector;
  return seletor && seletor !== 'ng-component' ? seletor : componente.name;
}

/**
 * Componentes da tela: os ligados às rotas (`idsRaiz`) mais todos os que aparecem, direta ou
 * indiretamente, nos templates deles, seguindo o campo `filhos` do registro.
 */
export function componentesDaTela(idsRaiz: string[], registro: { id: string; filhos: string[] }[]): Set<string> {
  const porId = new Map(registro.map((componente) => [componente.id, componente]));
  const encontrados = new Set<string>();
  const pendentes = idsRaiz.filter((id) => porId.has(id));
  while (pendentes.length) {
    const id = pendentes.pop()!;
    if (!encontrados.has(id)) {
      encontrados.add(id);
      pendentes.push(...(porId.get(id)?.filhos ?? []));
    }
  }
  return encontrados;
}

/** Acompanha a navegação e guarda a última rota visitada fora de `/_proto`. */
@Injectable({ providedIn: 'root' })
export class TelaAtualService {
  private readonly router = inject(Router);

  readonly tela = signal<TelaAtual | null>(ler<TelaAtual | null>(CHAVE, null));

  constructor() {
    this.router.events
      .pipe(filter((evento): evento is NavigationEnd => evento instanceof NavigationEnd))
      .subscribe((evento) => this.registrar(evento.urlAfterRedirects));
  }

  esquecer(): void {
    this.tela.set(null);
    gravar(CHAVE, null);
  }

  private registrar(url: string): void {
    if (url.startsWith('/_proto')) {
      return;
    }
    const tela: TelaAtual = { url, idsRaiz: this.idsDasRotasAtivas() };
    this.tela.set(tela);
    gravar(CHAVE, tela);
  }

  private idsDasRotasAtivas(): string[] {
    const ids: string[] = [];
    const percorrer = (rota: ActivatedRouteSnapshot): void => {
      if (rota.component) {
        const id = idDoComponente(rota.component);
        // Os componentes do prototipador têm todos seletor começando com `proto-`.
        if (!id.startsWith('proto-') && !ids.includes(id)) {
          ids.push(id);
        }
      }
      rota.children.forEach(percorrer);
    };
    // A raiz da árvore aponta para o componente de bootstrap, que não é ligado a nenhuma rota.
    this.router.routerState.snapshot.root.children.forEach(percorrer);
    return ids;
  }
}

import { TranslateLoader } from '@ngx-translate/core';
import { Observable, catchError, forkJoin, map, of } from 'rxjs';

import { IDIOMAS, IDIOMA_TAGS } from './idiomas';

type Traducoes = Record<string, unknown>;

function ehObjeto(valor: unknown): valor is Traducoes {
  return typeof valor === 'object' && valor !== null && !Array.isArray(valor);
}

/** Une as chaves dos arquivos de todos os idiomas, mantendo a estrutura. */
function unir(destino: Traducoes, origem: Traducoes): Traducoes {
  for (const [chave, valor] of Object.entries(origem)) {
    const atual = destino[chave];
    if (ehObjeto(atual) && ehObjeto(valor)) {
      unir(atual, valor);
    } else if (!ehObjeto(atual)) {
      destino[chave] = ehObjeto(valor) ? unir({}, valor) : valor;
    }
  }
  return destino;
}

/** Troca cada valor pelo caminho completo da chave. Serve para chaves aninhadas e planas. */
function trocarPelasChaves(traducoes: Traducoes, prefixo = ''): Traducoes {
  const resultado: Traducoes = {};
  for (const [chave, valor] of Object.entries(traducoes)) {
    const caminho = prefixo ? `${prefixo}.${chave}` : chave;
    resultado[chave] = ehObjeto(valor) ? trocarPelasChaves(valor, caminho) : caminho;
  }
  return resultado;
}

/**
 * Envolve o carregador de traduções do projeto. Idiomas reais vão direto ao original;
 * o pseudo-idioma `proto-tags` devolve as chaves no lugar dos textos.
 */
export class CarregadorComTags implements TranslateLoader {
  constructor(private readonly original: TranslateLoader) {}

  getTranslation(idioma: string): Observable<unknown> {
    if (idioma !== IDIOMA_TAGS) {
      return this.original.getTranslation(idioma);
    }
    const arquivos = IDIOMAS.map(({ codigo }) =>
      this.original.getTranslation(codigo).pipe(catchError(() => of({}))),
    );
    return forkJoin(arquivos).pipe(
      map((lista) => trocarPelasChaves(lista.reduce<Traducoes>((uniao, t) => unir(uniao, t), {}))),
    );
  }
}

export function comExibirTags(original: TranslateLoader): TranslateLoader {
  return new CarregadorComTags(original);
}

import { Injectable, inject, signal } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';

import { gravar, ler } from '../moldura/armazenamento';
import { IdiomaService } from './idioma.service';
import { IDIOMA_TAGS } from './idiomas';

const CHAVE = 'proto.exibirTags';

/**
 * Modo "exibir tags" (opção Tag do seletor): troca o idioma pelo pseudo-idioma `proto-tags`.
 * O idioma escolhido é mantido e volta a valer ao desligar. É o único ponto que chama `use`.
 */
@Injectable({ providedIn: 'root' })
export class ExibirTagsService {
  private readonly traducao = inject(TranslateService);
  private readonly idioma = inject(IdiomaService);

  readonly ligado = signal<boolean>(ler<unknown>(CHAVE, false) === true);

  constructor() {
    this.traducao.addLangs([IDIOMA_TAGS]);
    this.aplicar();
  }

  definir(ligado: boolean): void {
    this.ligado.set(ligado);
    gravar(CHAVE, ligado);
    this.aplicar();
  }

  private aplicar(): void {
    this.traducao.use(this.ligado() ? IDIOMA_TAGS : this.idioma.idioma());
  }
}

import { Injectable, inject, signal } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';

import { gravar, ler } from '../moldura/armazenamento';
import { CodigoIdioma, IDIOMAS, ehIdioma } from './idiomas';

const CHAVE = 'proto.idioma';

/**
 * Idioma escolhido no seletor do topo. Vale para a aplicação inteira.
 * Quem aplica a troca no serviço de tradução é o ExibirTagsService.
 */
@Injectable({ providedIn: 'root' })
export class IdiomaService {
  private readonly traducao = inject(TranslateService);

  readonly idioma = signal<CodigoIdioma>(this.idiomaInicial());

  escolher(codigo: CodigoIdioma): void {
    this.idioma.set(codigo);
    gravar(CHAVE, codigo);
  }

  private idiomaInicial(): CodigoIdioma {
    const guardado = ler<unknown>(CHAVE, null);
    if (ehIdioma(guardado)) {
      return guardado;
    }
    const doProjeto = this.traducao.currentLang || this.traducao.defaultLang;
    return ehIdioma(doProjeto) ? doProjeto : IDIOMAS[0].codigo;
  }
}

// Códigos de idioma usados pelo projeto. Devem bater com `i18n.idiomas` do prototipador.config.json.
export const IDIOMAS = [
  { codigo: 'pt', rotulo: 'PT' },
  { codigo: 'en', rotulo: 'EN' },
  { codigo: 'es', rotulo: 'ES' },
] as const;

export type CodigoIdioma = (typeof IDIOMAS)[number]['codigo'];

/** Pseudo-idioma do modo "exibir tags": cada texto é a própria chave. */
export const IDIOMA_TAGS = 'proto-tags';

export function ehIdioma(valor: unknown): valor is CodigoIdioma {
  return IDIOMAS.some((idioma) => idioma.codigo === valor);
}

