import {
  ApplicationRef,
  Component,
  ComponentRef,
  EnvironmentInjector,
  EnvironmentProviders,
  Injector,
  NgZone,
  OnDestroy,
  Provider,
  Type,
  ViewChild,
  ViewContainerRef,
  computed,
  createEnvironmentInjector,
  effect,
  inject,
  signal,
  untracked,
} from '@angular/core';
import { filter, first } from 'rxjs';

import type { ComponenteRegistrado } from '../../modelo/tipos';
import { TesteEstadoService } from '../teste-estado.service';

/** Espera sem novas edições antes de aplicá-las ao componente. */
const ESPERA_DE_EDICAO_MS = 150;
/** Limite de espera pela tela estabilizar antes da ação do usuário. */
const ESPERA_MAXIMA_DA_ACAO_MS = 3000;

interface Assinatura {
  unsubscribe(): void;
}

/** Renderiza o componente escolhido sozinho, no estado escolhido e com as edições. */
@Component({
  selector: 'proto-teste-palco',
  standalone: true,
  templateUrl: './palco.component.html',
  styleUrl: './palco.component.css',
})
export class PalcoComponent implements OnDestroy {
  protected readonly estado = inject(TesteEstadoService);
  private readonly injetorDeAmbiente = inject(EnvironmentInjector);
  private readonly aplicacao = inject(ApplicationRef);
  private readonly zona = inject(NgZone);

  @ViewChild('ancora', { read: ViewContainerRef, static: true })
  private readonly ancora!: ViewContainerRef;

  protected readonly erro = signal<string | null>(null);
  protected readonly largura = computed(() => {
    const largura = this.estado.ajuste()?.largura;
    return typeof largura === 'number' ? `${largura}px` : (largura ?? '100%');
  });

  private ref: ComponentRef<unknown> | null = null;
  private injetorCriado: EnvironmentInjector | null = null;
  private assinaturas: Assinatura[] = [];
  /** Valores já aplicados com setInput, para só reaplicar o que mudou. */
  private aplicados: Record<string, unknown> = {};
  /** Valores da última criação; depois de uma falha, só vale tentar de novo se mudarem. */
  private valoresTentados: Record<string, unknown> | null = null;
  private tentativa = 0;
  private espera: ReturnType<typeof setTimeout> | undefined;

  constructor() {
    // O estado muda a versão ao trocar de componente ou de estado e ao restaurar.
    effect(() => {
      if (this.estado.versao() > 0) {
        untracked(() => this.recriar(this.estado.selecionado()));
      }
    });

    effect(() => {
      const valores = this.estado.valores();
      clearTimeout(this.espera);
      this.espera = setTimeout(() => this.atualizar(valores), ESPERA_DE_EDICAO_MS);
    });
  }

  ngOnDestroy(): void {
    clearTimeout(this.espera);
    this.destruir();
  }

  private async recriar(componente: ComponenteRegistrado | null): Promise<void> {
    const tentativa = ++this.tentativa;
    this.destruir();
    this.erro.set(null);
    if (!componente) {
      return;
    }

    let classe: unknown;
    try {
      classe = await componente.carregar();
    } catch (erro) {
      if (tentativa === this.tentativa) {
        this.erro.set(mensagemDe(erro));
      }
      return;
    }
    // Outro componente foi pedido enquanto este carregava.
    if (tentativa !== this.tentativa) {
      return;
    }

    const ajuste = this.estado.ajuste();
    const estadoAtual = this.estado.estado();
    this.valoresTentados = untracked(() => this.estado.valores());
    try {
      // Provedores comuns entram num injetor de elemento, para vencer o que vem da árvore da
      // área de teste (ex.: ActivatedRoute); os de ambiente (provideX) num injetor de ambiente.
      const provedores = [...(ajuste?.provedores ?? []), ...estadoAtual.provedores];
      const deAmbiente = provedores.filter(ehDeAmbiente);
      const comuns = provedores.filter((provedor): provedor is Provider => !ehDeAmbiente(provedor));
      this.injetorCriado = createEnvironmentInjector(deAmbiente, this.injetorDeAmbiente);
      this.ref = this.ancora.createComponent(classe as Type<unknown>, {
        injector: Injector.create({ providers: comuns, parent: this.ancora.injector }),
        environmentInjector: this.injetorCriado,
        projectableNodes: ajuste?.conteudo === undefined ? undefined : [[document.createTextNode(ajuste.conteudo)]],
      });
      this.assinarSaidas(componente);
      this.aplicar(componente, this.valoresTentados);

      // A ação do usuário vem depois que a tela termina de carregar, como aconteceria de verdade.
      if (estadoAtual.acao) {
        await this.esperarEstabilizar();
        if (tentativa !== this.tentativa || !this.ref) {
          return;
        }
        await estadoAtual.acao(this.ref.instance);
        if (tentativa === this.tentativa && this.ref) {
          this.ref.changeDetectorRef.detectChanges();
        }
      }
    } catch (erro) {
      if (tentativa === this.tentativa) {
        this.falhar(erro);
      }
    }
  }

  /** Espera não haver carregamento nem tarefa pendente (ou o limite), sem segurar a estabilidade com o próprio timer. */
  private esperarEstabilizar(): Promise<void> {
    // Os dois avisos chegam fora da zona do Angular; a ação continua dentro dela, para a tela se atualizar.
    return new Promise((resolver) => {
      const continuar = () => this.zona.run(() => resolver());
      const assinatura = this.aplicacao.isStable.pipe(filter(Boolean), first()).subscribe(continuar);
      this.zona.runOutsideAngular(() =>
        setTimeout(() => {
          assinatura.unsubscribe();
          continuar();
        }, ESPERA_MAXIMA_DA_ACAO_MS),
      );
    });
  }

  /** Aplica as edições. Se algum input deixou de ser definido, só recriando volta ao padrão do componente. */
  private atualizar(valores: Record<string, unknown>): void {
    const componente = this.estado.selecionado();
    if (!componente) {
      return;
    }
    // Depois de uma falha não há componente: a edição pode ser justamente o que faltava (ex.: input obrigatório).
    if (!this.ref) {
      if (this.erro() && valores !== this.valoresTentados) {
        this.recriar(componente);
      }
      return;
    }
    const removidos = Object.keys(this.aplicados).some((nome) => !(nome in valores));
    if (removidos) {
      this.recriar(componente);
      return;
    }
    try {
      this.aplicar(componente, valores);
    } catch (erro) {
      this.falhar(erro);
    }
  }

  private aplicar(componente: ComponenteRegistrado, valores: Record<string, unknown>): void {
    const ref = this.ref!;
    const nomes = new Set(componente.inputs.map((input) => input.nome));
    for (const [nome, valor] of Object.entries(valores)) {
      if (!nomes.has(nome)) {
        continue;
      }
      if (!(nome in this.aplicados) || !Object.is(this.aplicados[nome], valor)) {
        ref.setInput(nome, valor);
        this.aplicados[nome] = valor;
      }
    }
    ref.changeDetectorRef.detectChanges();
  }

  private assinarSaidas(componente: ComponenteRegistrado): void {
    const instancia = this.ref!.instance as Record<string, unknown>;
    for (const output of componente.outputs) {
      const emissor = instancia[output.propriedade] as { subscribe?: (fn: (valor: unknown) => void) => Assinatura };
      if (typeof emissor?.subscribe === 'function') {
        this.assinaturas.push(emissor.subscribe((valor) => this.estado.registrarEvento(output.nome, valor)));
      }
    }
  }

  private falhar(erro: unknown): void {
    console.warn('[proto] Falha ao renderizar o componente na área de teste.', erro);
    this.destruir();
    this.erro.set(mensagemDe(erro));
  }

  private destruir(): void {
    this.assinaturas.forEach((assinatura) => assinatura.unsubscribe());
    this.assinaturas = [];
    this.ref?.destroy();
    this.ref = null;
    this.injetorCriado?.destroy();
    this.injetorCriado = null;
    this.aplicados = {};
    this.ancora?.clear();
  }
}

/** `provideHttpClient()` e afins só valem num injetor de ambiente. */
function ehDeAmbiente(provedor: Provider | EnvironmentProviders): provedor is EnvironmentProviders {
  return !!provedor && typeof provedor === 'object' && 'ɵproviders' in provedor;
}

function mensagemDe(erro: unknown): string {
  return erro instanceof Error ? erro.message : String(erro);
}

import { DestroyRef, EnvironmentProviders, Injectable, Provider, computed, effect, inject, signal, untracked } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';

import { AVISOS_DE_COMPONENTES, COMPONENTES } from '../gerado/componentes.gerado';
import type { ComponenteRegistrado } from '../modelo/tipos';
import { Ajuste, Estado } from './ajustar';
import { desserializar, resumir, serializar } from './valores';

export const ESTADO_PADRAO = 'Padrão';
const MAXIMO_DE_EVENTOS = 50;

export interface EventoEmitido {
  hora: Date;
  output: string;
  valor: string;
}

/** Ajuste carregado do `.proto.ts`, ou o erro de quando ele não pôde ser importado. */
export interface AjusteCarregado {
  ajuste: Ajuste | null;
  erro: string | null;
}

/** Estado do ajuste já na forma única usada pela área de teste. */
export interface EstadoDoComponente {
  nome: string;
  descricao: string | null;
  inputs: Estado['inputs'];
  provedores: (Provider | EnvironmentProviders)[];
  acao: Estado['acao'] | null;
}

const ESTADO_SEM_AJUSTE: EstadoDoComponente = { nome: ESTADO_PADRAO, descricao: null, inputs: {}, provedores: [], acao: null };

/**
 * Estado da área de teste. O componente e o estado vêm da URL (`?c=&v=`); as edições ficam
 * no sessionStorage, por componente e estado, para sobreviver ao recarregamento automático.
 */
@Injectable()
export class TesteEstadoService {
  private readonly router = inject(Router);
  private readonly rota = inject(ActivatedRoute);

  readonly registro: ComponenteRegistrado[] = COMPONENTES;
  readonly avisosGerais: string[] = AVISOS_DE_COMPONENTES;

  readonly ajustes = signal(new Map<string, AjusteCarregado>());
  readonly ajustesProntos = signal(false);

  private readonly idNaUrl = signal<string | null>(null);
  private readonly estadoNaUrl = signal<string | null>(null);

  readonly selecionado = computed(() => this.registro.find((c) => c.id === this.idNaUrl()) ?? null);
  /** Id pedido na URL que não existe no registro (componente apagado ou renomeado). */
  readonly idInexistente = computed(() => (this.idNaUrl() && !this.selecionado() ? this.idNaUrl() : null));
  readonly ajuste = computed(() => {
    const componente = this.selecionado();
    return componente ? (this.ajustes().get(componente.id)?.ajuste ?? null) : null;
  });

  /** Estados do ajuste (`estados` e depois `variacoes`); sem nenhum, só o Padrão. */
  readonly estados = computed<EstadoDoComponente[]>(() => {
    const ajuste = this.ajuste();
    const estados: EstadoDoComponente[] = [
      ...Object.entries(ajuste?.estados ?? {}).map(([nome, estado]) => ({
        nome,
        descricao: estado.descricao ?? null,
        inputs: estado.inputs ?? {},
        provedores: estado.provedores ?? [],
        acao: estado.acao ?? null,
      })),
      ...Object.entries(ajuste?.variacoes ?? {}).map(([nome, inputs]) => ({ ...ESTADO_SEM_AJUSTE, nome, inputs })),
    ];
    return estados.length ? estados : [ESTADO_SEM_AJUSTE];
  });
  readonly estado = computed(() => {
    const estados = this.estados();
    return estados.find((estado) => estado.nome === this.estadoNaUrl()) ?? estados[0];
  });

  /** Muda para o palco recriar o componente do zero (troca de componente ou de estado, restaurar). */
  readonly versao = signal(0);

  /**
   * Inputs definidos pelo estado, só os que existem no componente. Depende da versão para que
   * inputs criados por função (ex.: FormGroup) venham novos a cada recriação.
   */
  readonly valoresDoEstado = computed(() => {
    this.versao();
    const componente = this.selecionado();
    const estado = this.estado();
    if (!componente) {
      return {};
    }
    const valores = typeof estado.inputs === 'function' ? estado.inputs() : (estado.inputs ?? {});
    const nomes = new Set(componente.inputs.map((input) => input.nome));
    const conhecidos: Record<string, unknown> = {};
    for (const [nome, valor] of Object.entries(valores)) {
      if (nomes.has(nome)) {
        conhecidos[nome] = valor;
      } else {
        console.warn(`[proto] O estado "${estado.nome}" de ${componente.id} define "${nome}", que não é input do componente. Ignorado.`);
      }
    }
    return conhecidos;
  });

  readonly edicoes = signal<Record<string, unknown>>({});
  /** O que o palco aplica: só os inputs que o estado define ou que o usuário editou. */
  readonly valores = computed(() => ({ ...this.valoresDoEstado(), ...this.edicoes() }));

  readonly eventos = signal<EventoEmitido[]>([]);

  constructor() {
    const assinatura = this.rota.queryParamMap.subscribe((parametros) => {
      this.idNaUrl.set(parametros.get('c'));
      this.estadoNaUrl.set(parametros.get('v'));
    });
    inject(DestroyRef).onDestroy(() => assinatura.unsubscribe());

    this.carregarAjustes();

    // Ao mudar de componente ou de estado, retoma as edições guardadas e recria o componente.
    let anterior: string | null = null;
    effect(
      () => {
        const componente = this.selecionado();
        const estado = this.estado().nome;
        if (!this.ajustesProntos()) {
          return;
        }
        untracked(() => {
          if (componente?.id !== anterior) {
            this.eventos.set([]);
            anterior = componente?.id ?? null;
          }
          this.edicoes.set(componente ? lerEdicoes(componente.id, estado) : {});
          this.versao.update((v) => v + 1);
        });
      },
      { allowSignalWrites: true },
    );
  }

  selecionar(id: string): void {
    this.navegar({ c: id, v: null });
  }

  escolherEstado(nome: string): void {
    if (nome === this.estado().nome) {
      return;
    }
    const componente = this.selecionado();
    if (componente) {
      // Trocar de estado descarta as edições do atual e as que estavam guardadas para o novo.
      apagarEdicoes(componente.id, this.estado().nome);
      apagarEdicoes(componente.id, nome);
    }
    this.navegar({ v: nome });
  }

  editar(nome: string, valor: unknown): void {
    this.edicoes.update((edicoes) => ({ ...edicoes, [nome]: valor }));
    const componente = this.selecionado();
    if (componente) {
      gravarEdicoes(componente.id, this.estado().nome, this.edicoes());
    }
  }

  restaurar(): void {
    const componente = this.selecionado();
    if (componente) {
      apagarEdicoes(componente.id, this.estado().nome);
    }
    this.edicoes.set({});
    this.versao.update((v) => v + 1);
  }

  registrarEvento(output: string, valor: unknown): void {
    const evento: EventoEmitido = { hora: new Date(), output, valor: resumir(valor) };
    this.eventos.update((eventos) => [evento, ...eventos].slice(0, MAXIMO_DE_EVENTOS));
  }

  limparEventos(): void {
    this.eventos.set([]);
  }

  /** Avisos que ainda valem, por id: um input não editável deixa de ser problema se o ajuste o cobre. */
  readonly avisos = computed(() => {
    const porId = new Map<string, string[]>();
    for (const componente of this.registro) {
      const carregado = this.ajustes().get(componente.id);
      const ajuste = carregado?.ajuste;
      const cobertos = new Set([
        ...Object.keys(ajuste?.tipos ?? {}),
        ...Object.values(ajuste?.variacoes ?? {}).flatMap((valores) => Object.keys(valores)),
        ...Object.values(ajuste?.estados ?? {}).flatMap((estado) =>
          Object.keys((typeof estado.inputs === 'function' ? estado.inputs() : estado.inputs) ?? {}),
        ),
      ]);
      const avisos = componente.avisos.filter((aviso) => {
        const input = /^Input "([^".[]+)/.exec(aviso)?.[1];
        return !input || !cobertos.has(input);
      });
      porId.set(componente.id, carregado?.erro ? [`Arquivo de ajuste: ${carregado.erro}`, ...avisos] : avisos);
    }
    return porId;
  });

  private navegar(parametros: Record<string, string | null>): void {
    this.router.navigate([], { relativeTo: this.rota, queryParams: parametros, queryParamsHandling: 'merge' });
  }

  private async carregarAjustes(): Promise<void> {
    const carregados = await Promise.all(
      this.registro
        .filter((componente) => componente.ajuste)
        .map(async (componente): Promise<[string, AjusteCarregado]> => {
          try {
            const ajuste = await componente.ajuste!();
            if (!ajuste || typeof ajuste !== 'object') {
              return [componente.id, { ajuste: null, erro: 'o export default não é um objeto de ajuste.' }];
            }
            return [componente.id, { ajuste: ajuste as Ajuste, erro: null }];
          } catch (erro) {
            console.warn(`[proto] Não foi possível carregar o ajuste de ${componente.id}.`, erro);
            return [componente.id, { ajuste: null, erro: (erro as Error).message }];
          }
        }),
    );
    this.ajustes.set(new Map(carregados));
    this.ajustesProntos.set(true);
  }
}

// ---------- sessionStorage ----------

const chaveDasEdicoes = (id: string, estado: string) => `proto.teste.edicoes:${id}:${estado}`;

function lerEdicoes(id: string, estado: string): Record<string, unknown> {
  try {
    const texto = sessionStorage.getItem(chaveDasEdicoes(id, estado));
    return texto ? desserializar(texto) : {};
  } catch {
    return {};
  }
}

function gravarEdicoes(id: string, estado: string, edicoes: Record<string, unknown>): void {
  try {
    sessionStorage.setItem(chaveDasEdicoes(id, estado), serializar(edicoes));
  } catch {
    // Sem armazenamento, as edições valem só até recarregar.
  }
}

function apagarEdicoes(id: string, estado: string): void {
  try {
    sessionStorage.removeItem(chaveDasEdicoes(id, estado));
  } catch {
    // Nada a apagar.
  }
}

import { Component, inject, signal } from '@angular/core';

import { gravar, ler } from '../moldura/armazenamento';
import { ControlesComponent } from './controles/controles.component';
import { ListaComponent } from './lista/lista.component';
import { PalcoComponent } from './palco/palco.component';
import { TesteEstadoService } from './teste-estado.service';

const CHAVE_CONTROLES = 'proto.teste.controlesAbertos';

/** Aba Área de teste: o palco ocupa a área toda; árvore e controles abrem por cima dele. */
@Component({
  selector: 'proto-teste',
  standalone: true,
  imports: [ListaComponent, PalcoComponent, ControlesComponent],
  providers: [TesteEstadoService],
  template: `
    <div class="proto-teste__barra">
      <button
        type="button"
        class="proto-teste__botao"
        [class.proto-teste__botao--ativo]="arvoreAberta()"
        [attr.aria-expanded]="arvoreAberta()"
        (click)="arvoreAberta.set(!arvoreAberta())"
      >
        <i class="pi pi-sitemap"></i> Componentes
      </button>
      @if (estado.selecionado(); as componente) {
        <span class="proto-teste__atual">{{ componente.id }}</span>
      }
      <button
        type="button"
        class="proto-teste__botao"
        [class.proto-teste__botao--ativo]="controlesAbertos()"
        [attr.aria-expanded]="controlesAbertos()"
        (click)="alternarControles()"
      >
        <i class="pi pi-sliders-h"></i> Controles
        @if (estado.eventos().length) {
          <span class="proto-teste__contagem">{{ estado.eventos().length }}</span>
        }
      </button>
    </div>

    <div class="proto-teste__corpo">
      <proto-teste-palco class="proto-teste__palco" />
      @if (arvoreAberta()) {
        <proto-teste-lista class="proto-teste__painel proto-teste__painel--esquerda" (escolher)="arvoreAberta.set(false)" (fechar)="arvoreAberta.set(false)" />
      }
      @if (controlesAbertos()) {
        <proto-teste-controles class="proto-teste__painel proto-teste__painel--direita" (fechar)="alternarControles()" />
      }
    </div>
  `,
  styles: `
    :host {
      display: flex;
      flex-direction: column;
      height: 100%;
      min-height: 0;
    }

    .proto-teste__barra {
      flex: 0 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      height: 44px;
      padding: 0 8px;
      border-bottom: 1px solid #e4e6ea;
    }

    .proto-teste__botao {
      display: flex;
      align-items: center;
      gap: 6px;
      height: 30px;
      padding: 0 10px;
      border: none;
      border-radius: 6px;
      background: none;
      color: var(--text-color);
      font: inherit;
      font-size: 0.8125rem;
      cursor: pointer;
    }

    .proto-teste__botao:hover {
      background: rgba(0, 0, 0, 0.04);
    }

    .proto-teste__botao--ativo,
    .proto-teste__botao--ativo:hover {
      background: rgba(0, 0, 0, 0.06);
      color: var(--primary-color);
    }

    .proto-teste__botao .pi {
      font-size: 0.8125rem;
    }

    .proto-teste__atual {
      min-width: 0;
      overflow: hidden;
      color: var(--text-color-secondary);
      font-size: 0.8125rem;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .proto-teste__contagem {
      min-width: 18px;
      padding: 0 4px;
      border-radius: 9px;
      background: var(--primary-color);
      color: #fff;
      font-size: 0.6875rem;
      line-height: 18px;
      text-align: center;
    }

    .proto-teste__corpo {
      position: relative;
      flex: 1;
      min-height: 0;
    }

    /* isolation: os z-index da tela ficam contidos no palco e não passam por cima dos painéis. */
    .proto-teste__palco {
      position: absolute;
      inset: 0;
      overflow: auto;
      isolation: isolate;
    }

    .proto-teste__painel {
      position: absolute;
      top: 8px;
      bottom: 8px;
      z-index: 1;
      box-sizing: border-box;
      max-width: calc(100% - 16px);
      overflow: auto;
      border: 1px solid #e4e6ea;
      border-radius: 8px;
      background: #fff;
      box-shadow: 0 6px 20px rgba(0, 0, 0, 0.12);
    }

    .proto-teste__painel--esquerda {
      left: 8px;
      width: 300px;
    }

    .proto-teste__painel--direita {
      right: 8px;
      width: 360px;
    }
  `,
})
export class TesteComponent {
  protected readonly estado = inject(TesteEstadoService);

  // A árvore começa aberta só quando ainda não há componente escolhido.
  protected readonly arvoreAberta = signal(!this.estado.selecionado());
  protected readonly controlesAbertos = signal<boolean>(ler<unknown>(CHAVE_CONTROLES, false) === true);

  protected alternarControles(): void {
    this.controlesAbertos.update((valor) => !valor);
    gravar(CHAVE_CONTROLES, this.controlesAbertos());
  }
}

// Funções puras sobre os valores dos inputs: valor inicial por tipo, guarda no sessionStorage e resumo.
import type { TipoCampo } from '../modelo/tipos';

/** Valor de um campo novo (item de lista, objeto preenchido, nulo trocado por valor). */
export function valorInicial(tipo: TipoCampo): unknown {
  switch (tipo.tipo) {
    case 'texto':
      return '';
    case 'numero':
      return 0;
    case 'booleano':
      return false;
    case 'data':
      return new Date();
    case 'opcoes':
      return tipo.valores[0];
    case 'lista':
      return [];
    case 'objeto':
      return Object.fromEntries(
        tipo.campos.filter((campo) => !campo.opcional).map((campo) => [campo.nome, campo.aceitaNulo ? null : valorInicial(campo.tipo)]),
      );
    case 'naoEditavel':
      return undefined;
  }
}

// ---------- Guarda das edições ----------
// JSON perde `undefined` e `Date`; os dois são marcados para voltar como eram.

const MARCA = '@proto';
const INDEFINIDO = Symbol('indefinido');

export function serializar(valores: Record<string, unknown>): string {
  return JSON.stringify(valores, function (this: Record<string, unknown>, chave, valor) {
    const bruto = this[chave];
    if (bruto instanceof Date) {
      return { [MARCA]: 'data', valor: bruto.toISOString() };
    }
    if (valor === undefined && chave !== '') {
      return { [MARCA]: 'indefinido' };
    }
    return valor;
  });
}

export function desserializar(texto: string): Record<string, unknown> {
  const lido = JSON.parse(texto, (_, valor) => {
    if (valor && typeof valor === 'object' && MARCA in valor) {
      return valor[MARCA] === 'data' ? new Date(valor.valor) : INDEFINIDO;
    }
    return valor;
  });
  return restaurarIndefinidos(lido) as Record<string, unknown>;
}

/** No primeiro nível o indefinido é um valor (aplicado ao input); dentro de objetos, chave ausente. */
function restaurarIndefinidos(valor: unknown, nivel = 0): unknown {
  if (Array.isArray(valor)) {
    return valor.map((item) => (item === INDEFINIDO ? undefined : restaurarIndefinidos(item, nivel + 1)));
  }
  if (valor && typeof valor === 'object' && !(valor instanceof Date)) {
    const objeto: Record<string, unknown> = {};
    for (const [chave, item] of Object.entries(valor)) {
      if (item === INDEFINIDO) {
        if (nivel === 0) {
          objeto[chave] = undefined;
        }
      } else {
        objeto[chave] = restaurarIndefinidos(item, nivel + 1);
      }
    }
    return objeto;
  }
  return valor;
}

// ---------- Resumo dos eventos ----------

const TAMANHO_DO_RESUMO = 200;

/** JSON resumido, até 200 caracteres, que aguenta eventos do DOM e referências circulares. */
export function resumir(valor: unknown): string {
  if (valor === undefined) {
    return 'undefined';
  }
  const vistos = new WeakSet<object>();
  let texto: string;
  try {
    texto = JSON.stringify(valor, (_, item) => {
      if (typeof Event !== 'undefined' && item instanceof Event) {
        return `[${item.constructor.name} ${item.type}]`;
      }
      if (typeof Node !== 'undefined' && item instanceof Node) {
        return `[${item.nodeName.toLowerCase()}]`;
      }
      if (typeof item === 'function') {
        return '[função]';
      }
      if (item && typeof item === 'object') {
        if (vistos.has(item)) {
          return '[circular]';
        }
        vistos.add(item);
      }
      return item;
    }) ?? String(valor);
  } catch {
    texto = String(valor);
  }
  return texto.length > TAMANHO_DO_RESUMO ? `${texto.slice(0, TAMANHO_DO_RESUMO - 1)}…` : texto;
}

